insert into public.cefr_levels (id, name, name_vi, description, sort_order) values
  ('A1', 'Beginner', 'Mới bắt đầu', 'Giao tiếp cơ bản: chào hỏi, giới thiệu bản thân, nói về thói quen hằng ngày.', 1),
  ('A2', 'Elementary', 'Sơ cấp', 'Kể lại sự việc trong quá khứ, nói về kế hoạch và các tình huống quen thuộc.', 2),
  ('B1', 'Intermediate', 'Trung cấp', 'Chia sẻ trải nghiệm, nêu ý kiến và xử lý phần lớn tình huống khi đi làm, đi du lịch.', 3),
  ('B2', 'Upper Intermediate', 'Trung cao cấp', 'Thảo luận chủ đề trừu tượng, lập luận rõ ràng, giao tiếp trôi chảy với người bản ngữ.', 4),
  ('C1', 'Advanced', 'Cao cấp', 'Diễn đạt linh hoạt, chính xác trong môi trường học thuật và chuyên nghiệp.', 5),
  ('C2', 'Proficiency', 'Thành thạo', 'Hiểu và diễn đạt sắc thái tinh tế gần như người bản ngữ.', 6)
insert into public.modules (id, level_id, title, title_vi, description, category, sort_order) values
  ('a1-hello', 'A1', 'Hello & Introductions', 'Chào hỏi & giới thiệu', 'Chào hỏi, giới thiệu bản thân, động từ "to be" và thông tin cá nhân.', 'general', 1),
  ('a1-daily-life', 'A1', 'Everyday Life', 'Cuộc sống hằng ngày', 'Thói quen với hiện tại đơn và việc đang diễn ra với hiện tại tiếp diễn.', 'grammar', 2),
  ('a1-people-things', 'A1', 'People & Things', 'Người và đồ vật', 'Mạo từ, danh từ số nhiều, this/that và cách nói sở hữu.', 'grammar', 3),
  ('a1-home-city', 'A1', 'Home & City', 'Nhà cửa & thành phố', 'There is/there are, giới từ chỉ vị trí và động từ khuyết thiếu "can".', 'general', 4),
  ('a1-food-shopping', 'A1', 'Food & Shopping', 'Đồ ăn & mua sắm', 'Danh từ đếm được/không đếm được, gọi món và hỏi giá.', 'general', 5),
  ('a2-past', 'A2', 'Past Experiences', 'Kể chuyện quá khứ', 'Quá khứ đơn, quá khứ tiếp diễn, "used to" và kể lại một chuyến đi.', 'grammar', 1),
  ('a2-future', 'A2', 'Plans & Predictions', 'Kế hoạch & dự đoán', '"Be going to", "will", lịch hẹn và lời mời.', 'grammar', 2),
  ('a2-describing', 'A2', 'Describing & Comparing', 'Miêu tả & so sánh', 'So sánh hơn, so sánh nhất và cách nói về bổn phận, lời khuyên.', 'grammar', 3),
  ('b1-experiences', 'B1', 'Life Experiences', 'Trải nghiệm cuộc sống', 'Hiện tại hoàn thành và cách phân biệt với quá khứ đơn.', 'grammar', 1),
  ('b1-dev-teamwork', 'B1', 'Developer English: Teamwork', 'Tiếng Anh cho lập trình viên: Làm việc nhóm', 'Daily stand-up, code review và trao đổi với đồng nghiệp quốc tế.', 'developer', 2),
  ('b2-hypotheticals', 'B2', 'Hypothetical Situations', 'Tình huống giả định', 'Câu điều kiện loại 2, loại 3 và câu điều kiện hỗn hợp.', 'grammar', 1),
  ('c1-emphasis', 'C1', 'Formal Emphasis', 'Nhấn mạnh trang trọng', 'Đảo ngữ với trạng từ phủ định để nhấn mạnh.', 'grammar', 1),
  ('c2-nuance', 'C2', 'Precision & Nuance', 'Chính xác & sắc thái', 'Câu chẻ (cleft sentences) để làm nổi bật thông tin.', 'grammar', 1)
insert into public.lessons (id, module_id, level_id, title, title_vi, description, objectives, estimated_minutes, sort_order, vocabulary_ids, exercise_ids) values
  ('l-a1-greetings', 'a1-hello', 'A1', 'Greetings', 'Chào hỏi', 'Chào hỏi theo thời điểm trong ngày và giới thiệu tên.', array['Chào hỏi đúng thời điểm trong ngày', 'Giới thiệu tên của bạn', 'Đáp lại lời chào tự nhiên']::text[], 8, 1, array['v-hello', 'v-goodbye', 'v-name', 'v-meet']::text[], array['ex-a1-greetings']::text[]),
  ('l-a1-to-be', 'a1-hello', 'A1', 'The verb "to be"', 'Động từ "to be"', 'Am, is, are trong câu khẳng định, phủ định và câu hỏi.', array['Chọn đúng am / is / are theo chủ ngữ', 'Viết câu phủ định với "not"', 'Đặt câu hỏi Yes/No']::text[], 10, 2, array['v-friend', 'v-brother', 'v-happy']::text[], array['ex-a1-to-be']::text[]),
  ('l-a1-personal-info', 'a1-hello', 'A1', 'Numbers & personal information', 'Số đếm & thông tin cá nhân', 'Nói tuổi, số điện thoại, địa chỉ và ngày sinh.', array['Đọc số từ 1 đến 100, phân biệt -teen và -ty', 'Nói tuổi đúng cấu trúc "I''m + số"', 'Hỏi và trả lời số điện thoại, địa chỉ, sinh nhật']::text[], 10, 3, array['v-number', 'v-phone-number', 'v-age', 'v-birthday', 'v-address']::text[], array['ex-a1-personal-info']::text[]),
  ('l-a1-present-simple', 'a1-daily-life', 'A1', 'Present simple', 'Thì hiện tại đơn', 'Diễn tả thói quen và sự thật hiển nhiên.', array['Thêm -s/-es đúng với he/she/it', 'Dùng do/does trong câu hỏi và phủ định', 'Đặt trạng từ tần suất đúng vị trí']::text[], 12, 1, array['v-wake-up', 'v-breakfast', 'v-work', 'v-every-day']::text[], array['ex-a1-present-simple']::text[]),
  ('l-a1-reading-day', 'a1-daily-life', 'A1', 'Reading: A day in Da Nang', 'Đọc hiểu: Một ngày ở Đà Nẵng', 'Đọc đoạn văn ngắn về thói quen hằng ngày.', array['Hiểu đoạn văn ngắn về thói quen', 'Tìm thông tin cụ thể (giờ giấc, phương tiện)', 'Nhận biết thì hiện tại đơn trong ngữ cảnh']::text[], 8, 2, array['v-wake-up', 'v-breakfast', 'v-family']::text[], array['ex-a1-reading-day']::text[]),
  ('l-a1-present-continuous', 'a1-daily-life', 'A1', 'Present continuous: right now', 'Hiện tại tiếp diễn: việc đang xảy ra', 'Nói về việc đang diễn ra và phân biệt với hiện tại đơn.', array['Tạo câu với am/is/are + V-ing', 'Viết đúng chính tả V-ing', 'Phân biệt "bây giờ" và "thường xuyên"']::text[], 12, 3, array['v-cook', 'v-study', 'v-watch', 'v-listen', 'v-read']::text[], array['ex-a1-present-continuous']::text[]),
  ('l-a1-articles', 'a1-people-things', 'A1', 'Articles: a, an, the', 'Mạo từ a, an, the', 'Khi nào dùng a, an, the hoặc không dùng mạo từ.', array['Chọn a/an theo âm đầu', 'Dùng "the" cho thứ đã xác định', 'Nhận biết khi không cần mạo từ']::text[], 10, 1, array['v-water', 'v-friend']::text[], array['ex-a1-articles']::text[]),
  ('l-a1-plurals', 'a1-people-things', 'A1', 'Plural nouns & this/that/these/those', 'Danh từ số nhiều & this/that/these/those', 'Tạo danh từ số nhiều và chỉ đồ vật gần, xa.', array['Thêm -s/-es/-ies đúng quy tắc', 'Nhớ các danh từ số nhiều bất quy tắc thường gặp', 'Dùng đúng this, that, these, those']::text[], 10, 2, array['v-child', 'v-person', 'v-chair', 'v-table']::text[], array['ex-a1-plurals']::text[]),
  ('l-a1-possessives', 'a1-people-things', 'A1', 'Possessives: my, your & ''s', 'Sở hữu: my, your và ''s', 'Nói đồ vật, người thân thuộc về ai.', array['Dùng đúng tính từ sở hữu my, your, his, her, its, our, their', 'Dùng sở hữu cách ''s', 'Hỏi "Whose…?" và phân biệt its / it''s']::text[], 10, 3, array['v-mother', 'v-father', 'v-sister', 'v-husband', 'v-wife']::text[], array['ex-a1-possessives']::text[]),
  ('l-a1-there-is', 'a1-home-city', 'A1', 'There is / there are', 'There is / there are', 'Nói nơi nào đó "có" gì.', array['Dùng there is với số ít, there are với số nhiều', 'Đặt câu phủ định và câu hỏi', 'Tránh lỗi dịch "có" thành "have"']::text[], 10, 1, array['v-house', 'v-room', 'v-kitchen', 'v-park', 'v-market', 'v-bank']::text[], array['ex-a1-there-is']::text[]),
  ('l-a1-prepositions-place', 'a1-home-city', 'A1', 'Prepositions of place', 'Giới từ chỉ vị trí', 'Nói đồ vật, địa điểm ở đâu.', array['Dùng in, on, under, next to, between, behind, in front of, opposite', 'Phân biệt "in" (bên trong) và "on" (trên bề mặt)', 'Chỉ vị trí cửa hàng, toà nhà trên phố']::text[], 10, 2, array['v-table', 'v-bed', 'v-door', 'v-window', 'v-next-to', 'v-between', 'v-under', 'v-near']::text[], array['ex-a1-prepositions-place']::text[]),
  ('l-a1-can', 'a1-home-city', 'A1', 'Can and can’t', 'Can và can’t', 'Nói về khả năng và đưa ra lời đề nghị lịch sự.', array['Dùng can + động từ nguyên mẫu', 'Phát âm phân biệt can và can’t', 'Dùng "Can you…?" để nhờ vả, xin phép']::text[], 10, 3, array['v-swim', 'v-drive', 'v-cook', 'v-walk']::text[], array['ex-a1-can']::text[]),
  ('l-a1-countable', 'a1-food-shopping', 'A1', 'Countable & uncountable: some, any', 'Danh từ đếm được, không đếm được: some, any', 'Nói về đồ ăn với a/an, some, any, much, many.', array['Phân biệt danh từ đếm được và không đếm được', 'Dùng some trong câu khẳng định, any trong câu phủ định và câu hỏi', 'Dùng đơn vị đo: a glass of, a bottle of, a bowl of']::text[], 12, 1, array['v-rice', 'v-bread', 'v-egg', 'v-fruit', 'v-vegetable', 'v-milk']::text[], array['ex-a1-countable']::text[]),
  ('l-a1-ordering-food', 'a1-food-shopping', 'A1', 'At a restaurant: I''d like…', 'Ở nhà hàng: gọi món lịch sự', 'Gọi món, hỏi thực đơn và xin hoá đơn lịch sự.', array['Gọi món với I''d like… / Can I have…?', 'Hiểu câu hỏi của nhân viên phục vụ', 'Xin hoá đơn và thanh toán lịch sự']::text[], 10, 2, array['v-menu', 'v-bill', 'v-hungry', 'v-thirsty', 'v-coffee', 'v-tea']::text[], array['ex-a1-ordering-food']::text[]),
  ('l-a1-shopping', 'a1-food-shopping', 'A1', 'Shopping: how much is it?', 'Mua sắm: hỏi giá và thanh toán', 'Hỏi giá, nói giá tiền và chọn cách trả tiền.', array['Hỏi giá với How much is/are…?', 'Đọc giá tiền đồng và đô la', 'Nói rẻ, đắt, hỏi size và cách thanh toán']::text[], 10, 3, array['v-buy', 'v-pay', 'v-price', 'v-cheap', 'v-expensive', 'v-money', 'v-size']::text[], array['ex-a1-shopping']::text[]),
  ('l-a2-past-simple', 'a2-past', 'A2', 'Past simple', 'Thì quá khứ đơn', 'Kể lại sự việc đã xảy ra và kết thúc trong quá khứ.', array['Chia động từ có quy tắc với -ed', 'Nhớ các động từ bất quy tắc thường gặp', 'Đặt câu hỏi và phủ định với "did"']::text[], 12, 1, array['v-holiday', 'v-ticket', 'v-delicious']::text[], array['ex-a2-past-simple']::text[]),
  ('l-a2-past-continuous', 'a2-past', 'A2', 'Past continuous', 'Thì quá khứ tiếp diễn', 'Kể việc đang diễn ra tại một thời điểm trong quá khứ và việc bị cắt ngang.', array['Tạo câu với was/were + V-ing', 'Kết hợp quá khứ tiếp diễn với quá khứ đơn bằng when/while', 'Đặt bối cảnh khi kể chuyện']::text[], 12, 2, array['v-suddenly', 'v-happen', 'v-accident', 'v-rain']::text[], array['ex-a2-past-continuous']::text[]),
  ('l-a2-used-to', 'a2-past', 'A2', 'Used to', 'Used to: thói quen trong quá khứ', 'Nói về thói quen, trạng thái trước đây nay không còn.', array['Dùng used to + V nguyên mẫu', 'Đặt câu phủ định và câu hỏi với didn''t use to / Did… use to?', 'Phân biệt với hiện tại đơn']::text[], 10, 3, array['v-childhood', 'v-remember']::text[], array['ex-a2-used-to']::text[]),
  ('l-a2-reading-trip', 'a2-past', 'A2', 'Reading: A trip to Sa Pa', 'Đọc hiểu: Chuyến đi Sa Pa', 'Đọc một câu chuyện du lịch dùng quá khứ đơn và quá khứ tiếp diễn.', array['Hiểu trình tự sự việc trong một câu chuyện', 'Nhận ra quá khứ đơn và quá khứ tiếp diễn trong văn bản', 'Tìm thông tin chi tiết']::text[], 10, 4, array['v-journey', 'v-weather', 'v-view', 'v-finally']::text[], array['ex-a2-reading-trip']::text[]),
  ('l-a2-future', 'a2-future', 'A2', 'Going to vs will', 'Going to và will', 'Nói về kế hoạch, quyết định tức thì và dự đoán.', array['Dùng "be going to" cho kế hoạch đã định', 'Dùng "will" cho quyết định tức thì và lời hứa', 'Chọn đúng cách dự đoán']::text[], 10, 1, array['v-plan', 'v-meeting']::text[], array['ex-a2-future']::text[]),
  ('l-a2-future-arrangements', 'a2-future', 'A2', 'Arrangements and timetables', 'Lịch hẹn và thời gian biểu', 'Dùng hiện tại tiếp diễn và hiện tại đơn để nói về tương lai.', array['Dùng hiện tại tiếp diễn cho lịch hẹn đã sắp xếp', 'Dùng hiện tại đơn cho lịch trình cố định', 'Chọn giữa going to, will và hiện tại tiếp diễn']::text[], 10, 2, array['v-appointment', 'v-arrange', 'v-weekend', 'v-busy']::text[], array['ex-a2-future-arrangements']::text[]),
  ('l-a2-invitations', 'a2-future', 'A2', 'Suggestions & invitations', 'Rủ rê và mời mọc', 'Đưa ra gợi ý, mời và nhận lời hoặc từ chối lịch sự.', array['Gợi ý với Let''s / Why don''t we / How about', 'Mời với Would you like to…?', 'Nhận lời và từ chối lịch sự']::text[], 10, 3, array['v-invite', 'v-free-time', 'v-busy', 'v-probably']::text[], array['ex-a2-invitations']::text[]),
  ('l-a2-comparatives', 'a2-describing', 'A2', 'Comparatives', 'So sánh hơn', 'So sánh hai người, hai nơi, hai đồ vật.', array['Tạo tính từ so sánh hơn với -er và more', 'Nhớ các dạng bất quy tắc better, worse, further', 'Dùng as … as để nói "bằng nhau"']::text[], 12, 1, array['v-comfortable', 'v-crowded', 'v-quiet', 'v-noisy', 'v-modern']::text[], array['ex-a2-comparatives']::text[]),
  ('l-a2-superlatives', 'a2-describing', 'A2', 'Superlatives', 'So sánh nhất', 'Nói ai, cái gì là nhất trong một nhóm.', array['Tạo so sánh nhất với the -est và the most', 'Dùng in/of sau so sánh nhất', 'Nhớ the best, the worst']::text[], 10, 2, array['v-traditional', 'v-dangerous', 'v-safe', 'v-friendly']::text[], array['ex-a2-superlatives']::text[]),
  ('l-a2-obligation', 'a2-describing', 'A2', 'Must, have to, should', 'Must, have to, should', 'Nói về quy định, bổn phận và đưa lời khuyên.', array['Dùng must / have to cho việc bắt buộc', 'Phân biệt mustn''t (cấm) và don''t have to (không cần)', 'Khuyên với should / shouldn''t']::text[], 12, 3, array['v-rule', 'v-uniform', 'v-headache', 'v-medicine', 'v-healthy', 'v-exercise']::text[], array['ex-a2-obligation']::text[]),
  ('l-b1-present-perfect', 'b1-experiences', 'B1', 'Present perfect vs past simple', 'Hiện tại hoàn thành và quá khứ đơn', 'Phân biệt trải nghiệm/kết quả hiện tại với sự kiện có mốc thời gian.', array['Dùng hiện tại hoàn thành cho trải nghiệm', 'Phân biệt for và since', 'Không dùng hiện tại hoàn thành với mốc thời gian đã kết thúc']::text[], 14, 1, array['v-experience', 'v-improve', 'v-confident']::text[], array['ex-b1-present-perfect']::text[]),
  ('l-b1-standup', 'b1-dev-teamwork', 'B1', 'Speaking in daily stand-ups', 'Nói trong buổi daily stand-up', 'Báo cáo việc đã làm, sẽ làm và vấn đề gặp phải trong 60 giây.', array['Dùng cấu trúc Yesterday – Today – Blockers', 'Nói ngắn gọn, rõ ràng', 'Nhờ hỗ trợ một cách lịch sự']::text[], 10, 1, array['v-blocker', 'v-deadline', 'v-deploy', 'v-colleague']::text[], array['ex-b1-standup']::text[]),
  ('l-b1-code-review', 'b1-dev-teamwork', 'B1', 'Writing code review comments', 'Viết bình luận code review', 'Góp ý lịch sự, cụ thể và mang tính xây dựng.', array['Dùng câu hỏi gợi ý thay vì mệnh lệnh', 'Giải thích lý do của góp ý', 'Hiểu các viết tắt LGTM, nit, WIP']::text[], 9, 2, array['v-review', 'v-bug', 'v-improve']::text[], array['ex-b1-code-review']::text[]),
  ('l-b2-conditionals', 'b2-hypotheticals', 'B2', 'Second, third & mixed conditionals', 'Câu điều kiện loại 2, 3 và hỗn hợp', 'Diễn tả giả định trái với thực tế ở hiện tại và quá khứ.', array['Dùng câu điều kiện loại 2 cho giả định hiện tại', 'Dùng loại 3 để nói về hối tiếc trong quá khứ', 'Kết hợp hai loại trong câu điều kiện hỗn hợp']::text[], 14, 1, array['v-regret', 'v-trade-off', 'v-negotiate']::text[], array['ex-b2-conditionals']::text[]),
  ('l-c1-inversion', 'c1-emphasis', 'C1', 'Negative inversion', 'Đảo ngữ với trạng từ phủ định', 'Nhấn mạnh trong văn viết và bài nói trang trọng.', array['Đảo trợ động từ sau trạng từ phủ định', 'Dùng đúng No sooner … than / Hardly … when', 'Nhận biết khi nào đảo ngữ phù hợp với văn phong']::text[], 12, 1, array['v-scarcely', 'v-mitigate', 'v-nuance']::text[], array['ex-c1-inversion']::text[]),
  ('l-c2-cleft', 'c2-nuance', 'C2', 'Cleft sentences for focus', 'Câu chẻ để nhấn mạnh', 'Điều khiển trọng tâm thông tin bằng it-cleft và wh-cleft.', array['Tạo it-cleft để đối chiếu thông tin', 'Dùng wh-cleft để dẫn dắt ý chính', 'Chọn cấu trúc phù hợp với ý định giao tiếp']::text[], 12, 1, array['v-ubiquitous', 'v-equivocal', 'v-nuance']::text[], array['ex-c2-cleft']::text[])
insert into public.lesson_contents (lesson_id, position, block) values
  ('l-a1-greetings', 0, '{"type":"text","text":"Lời chào là câu đầu tiên trong mọi cuộc trò chuyện. Tiếng Anh có lời chào trang trọng và thân mật — chọn đúng sẽ giúp bạn tạo ấn tượng tốt."}'::jsonb),
  ('l-a1-greetings', 1, '{"type":"heading","text":"Chào theo thời điểm trong ngày"}'::jsonb),
  ('l-a1-greetings', 2, '{"type":"example","en":"Good morning!","vi":"Chào buổi sáng! (đến khoảng 12 giờ trưa)"}'::jsonb),
  ('l-a1-greetings', 3, '{"type":"example","en":"Good afternoon!","vi":"Chào buổi chiều! (12 giờ – khoảng 6 giờ tối)"}'::jsonb),
  ('l-a1-greetings', 4, '{"type":"example","en":"Good evening!","vi":"Chào buổi tối! (khi gặp ai đó vào buổi tối)"}'::jsonb),
  ('l-a1-greetings', 5, '{"type":"mistake","wrong":"Good night! (khi vừa gặp ai đó buổi tối)","right":"Good evening!","explanationVi":"\"Good night\" chỉ dùng khi tạm biệt hoặc trước khi đi ngủ, không dùng để chào khi gặp mặt."}'::jsonb),
  ('l-a1-greetings', 6, '{"type":"heading","text":"Giới thiệu bản thân"}'::jsonb),
  ('l-a1-greetings', 7, '{"type":"grammar","title":"Giới thiệu tên","structure":"My name is + tên.  /  I''m + tên.","explanationVi":"\"I''m\" là dạng rút gọn của \"I am\", tự nhiên hơn trong giao tiếp hằng ngày."}'::jsonb),
  ('l-a1-greetings', 8, '{"type":"example","en":"Hi, I''m Nam. Nice to meet you.","vi":"Chào bạn, mình là Nam. Rất vui được gặp bạn."}'::jsonb),
  ('l-a1-greetings', 9, '{"type":"example","en":"Nice to meet you, too.","vi":"Mình cũng rất vui được gặp bạn."}'::jsonb),
  ('l-a1-greetings', 10, '{"type":"tip","text":"Người bản ngữ thường nói \"Hi\" hoặc \"Hey\" với bạn bè, và \"Hello\" trong tình huống trung tính hoặc trang trọng hơn."}'::jsonb),
  ('l-a1-greetings', 11, '{"type":"vocabulary","wordIds":["v-hello","v-goodbye","v-name","v-meet"]}'::jsonb),
  ('l-a1-greetings', 12, '{"type":"exercise","exerciseId":"ex-a1-greetings"}'::jsonb),
  ('l-a1-to-be', 0, '{"type":"text","text":"\"To be\" có nghĩa là \"thì, là, ở\". Đây là động từ quan trọng nhất trong tiếng Anh — bạn dùng nó để nói tên, tuổi, nghề nghiệp, cảm xúc và vị trí."}'::jsonb),
  ('l-a1-to-be', 1, '{"type":"grammar","title":"Thể khẳng định","structure":"I + am  ·  He / She / It + is  ·  You / We / They + are","explanationVi":"Dạng rút gọn: I''m, he''s, she''s, it''s, you''re, we''re, they''re."}'::jsonb),
  ('l-a1-to-be', 2, '{"type":"example","en":"I am a student.","vi":"Tôi là sinh viên."}'::jsonb),
  ('l-a1-to-be', 3, '{"type":"example","en":"She is from Hue.","vi":"Cô ấy đến từ Huế."}'::jsonb),
  ('l-a1-to-be', 4, '{"type":"example","en":"They are at home.","vi":"Họ đang ở nhà."}'::jsonb),
  ('l-a1-to-be', 5, '{"type":"grammar","title":"Thể phủ định","structure":"S + am / is / are + not","explanationVi":"Rút gọn: is not = isn''t, are not = aren''t. \"Am not\" không có dạng rút gọn \"amn''t\" — dùng \"I''m not\"."}'::jsonb),
  ('l-a1-to-be', 6, '{"type":"example","en":"He isn''t tired.","vi":"Anh ấy không mệt."}'::jsonb),
  ('l-a1-to-be', 7, '{"type":"grammar","title":"Câu hỏi Yes/No","structure":"Am / Is / Are + S + ...?","explanationVi":"Đảo \"to be\" lên trước chủ ngữ. Trả lời ngắn: Yes, I am. / No, I''m not."}'::jsonb),
  ('l-a1-to-be', 8, '{"type":"example","en":"Are you happy? — Yes, I am.","vi":"Bạn có vui không? — Có."}'::jsonb),
  ('l-a1-to-be', 9, '{"type":"mistake","wrong":"I is a teacher.","right":"I am a teacher.","explanationVi":"\"I\" luôn đi với \"am\"."}'::jsonb),
  ('l-a1-to-be', 10, '{"type":"mistake","wrong":"She a doctor.","right":"She is a doctor.","explanationVi":"Tiếng Việt có thể bỏ \"là\", nhưng tiếng Anh bắt buộc phải có động từ \"to be\"."}'::jsonb),
  ('l-a1-to-be', 11, '{"type":"vocabulary","wordIds":["v-friend","v-brother","v-happy"]}'::jsonb),
  ('l-a1-to-be', 12, '{"type":"exercise","exerciseId":"ex-a1-to-be"}'::jsonb),
  ('l-a1-personal-info', 0, '{"type":"text","text":"Khi làm quen hay điền giấy tờ, bạn thường phải nói tuổi, số điện thoại và địa chỉ. Bài này giúp bạn nói những thông tin đó rõ ràng và đúng ngữ pháp."}'::jsonb),
  ('l-a1-personal-info', 1, '{"type":"heading","text":"Số đếm"}'::jsonb),
  ('l-a1-personal-info', 2, '{"type":"text","text":"1 one · 2 two · 3 three · 4 four · 5 five · 6 six · 7 seven · 8 eight · 9 nine · 10 ten · 11 eleven · 12 twelve · 13 thirteen · 20 twenty · 21 twenty-one · 30 thirty · 100 one hundred."}'::jsonb),
  ('l-a1-personal-info', 3, '{"type":"tip","text":"Nghe kỹ trọng âm: thirTEEN /θɜːˈtiːn/ (13) nhấn âm cuối, còn THIRty /ˈθɜːti/ (30) nhấn âm đầu. Tương tự: fourTEEN – FORty, fifTEEN – FIFty."}'::jsonb),
  ('l-a1-personal-info', 4, '{"type":"heading","text":"Nói tuổi"}'::jsonb),
  ('l-a1-personal-info', 5, '{"type":"grammar","title":"Tuổi","structure":"How old are you?  →  I''m + số (years old).","explanationVi":"Tiếng Anh dùng động từ \"be\" để nói tuổi, không dùng \"have\". Có thể thêm \"years old\" hoặc không: I''m 25. = I''m 25 years old."}'::jsonb),
  ('l-a1-personal-info', 6, '{"type":"example","en":"How old is your daughter? — She''s seven.","vi":"Con gái bạn mấy tuổi? — Cháu bảy tuổi."}'::jsonb),
  ('l-a1-personal-info', 7, '{"type":"mistake","wrong":"I have 25 years old.","right":"I''m 25 (years old).","explanationVi":"Dịch từng chữ \"tôi có 25 tuổi\" là lỗi rất phổ biến. Luôn dùng \"be\" để nói tuổi."}'::jsonb),
  ('l-a1-personal-info', 8, '{"type":"heading","text":"Số điện thoại, địa chỉ, sinh nhật"}'::jsonb),
  ('l-a1-personal-info', 9, '{"type":"example","en":"What''s your phone number? — It''s 0912 345 678.","vi":"Số điện thoại của bạn là gì? — Là 0912 345 678.","note":"Đọc từng chữ số; số 0 thường đọc là \"oh\" hoặc \"zero\"."}'::jsonb),
  ('l-a1-personal-info', 10, '{"type":"example","en":"Where do you live? — I live at 25 Le Loi Street.","vi":"Bạn sống ở đâu? — Tôi sống ở số 25 đường Lê Lợi."}'::jsonb),
  ('l-a1-personal-info', 11, '{"type":"example","en":"When is your birthday? — It''s on the 5th of May.","vi":"Sinh nhật bạn khi nào? — Vào ngày 5 tháng 5."}'::jsonb),
  ('l-a1-personal-info', 12, '{"type":"vocabulary","wordIds":["v-number","v-phone-number","v-age","v-birthday","v-address"]}'::jsonb),
  ('l-a1-personal-info', 13, '{"type":"exercise","exerciseId":"ex-a1-personal-info"}'::jsonb),
  ('l-a1-present-simple', 0, '{"type":"text","text":"Thì hiện tại đơn dùng để nói về thói quen, lịch trình lặp lại và sự thật luôn đúng."}'::jsonb),
  ('l-a1-present-simple', 1, '{"type":"grammar","title":"Khẳng định","structure":"I / You / We / They + V  ·  He / She / It + V-s/es","explanationVi":"Thêm \"-es\" khi động từ tận cùng bằng -o, -s, -sh, -ch, -x (go → goes, watch → watches). Phụ âm + y → -ies (study → studies)."}'::jsonb),
  ('l-a1-present-simple', 2, '{"type":"example","en":"I drink coffee every morning.","vi":"Tôi uống cà phê mỗi sáng."}'::jsonb),
  ('l-a1-present-simple', 3, '{"type":"example","en":"He watches football on Sundays.","vi":"Anh ấy xem bóng đá vào Chủ nhật."}'::jsonb),
  ('l-a1-present-simple', 4, '{"type":"grammar","title":"Phủ định & câu hỏi","structure":"S + don''t / doesn''t + V  ·  Do / Does + S + V?","explanationVi":"Khi đã có \"does\", động từ chính trở về nguyên mẫu: She doesn''t like (không phải likes)."}'::jsonb),
  ('l-a1-present-simple', 5, '{"type":"example","en":"She doesn''t eat meat.","vi":"Cô ấy không ăn thịt."}'::jsonb),
  ('l-a1-present-simple', 6, '{"type":"example","en":"Do you work from home?","vi":"Bạn có làm việc ở nhà không?"}'::jsonb),
  ('l-a1-present-simple', 7, '{"type":"heading","text":"Trạng từ tần suất"}'::jsonb),
  ('l-a1-present-simple', 8, '{"type":"text","text":"always (luôn luôn) → usually (thường xuyên) → often (thường) → sometimes (thỉnh thoảng) → rarely (hiếm khi) → never (không bao giờ). Chúng đứng trước động từ thường nhưng sau \"to be\"."}'::jsonb),
  ('l-a1-present-simple', 9, '{"type":"example","en":"I usually wake up at 6. She is never late.","vi":"Tôi thường dậy lúc 6 giờ. Cô ấy không bao giờ đến muộn."}'::jsonb),
  ('l-a1-present-simple', 10, '{"type":"mistake","wrong":"Does she likes music?","right":"Does she like music?","explanationVi":"Sau \"does\" dùng động từ nguyên mẫu, không thêm -s."}'::jsonb),
  ('l-a1-present-simple', 11, '{"type":"vocabulary","wordIds":["v-wake-up","v-breakfast","v-work","v-every-day"]}'::jsonb),
  ('l-a1-present-simple', 12, '{"type":"exercise","exerciseId":"ex-a1-present-simple"}'::jsonb),
  ('l-a1-reading-day', 0, '{"type":"text","text":"Mẹo đọc hiểu: đọc câu hỏi trước, sau đó đọc đoạn văn để tìm thông tin. Chú ý các từ chỉ thời gian như \"every day\", \"in the evening\", \"on Sundays\"."}'::jsonb),
  ('l-a1-reading-day', 1, '{"type":"heading","text":"Từ cần biết trước khi đọc"}'::jsonb),
  ('l-a1-reading-day', 2, '{"type":"example","en":"half past six","vi":"6 giờ 30 phút"}'::jsonb),
  ('l-a1-reading-day', 3, '{"type":"example","en":"by motorbike","vi":"bằng xe máy"}'::jsonb),
  ('l-a1-reading-day', 4, '{"type":"example","en":"visit her parents","vi":"thăm bố mẹ cô ấy"}'::jsonb),
  ('l-a1-reading-day', 5, '{"type":"tip","text":"\"By + phương tiện\" không có mạo từ: by bus, by car, by motorbike. Nhưng \"on foot\" (đi bộ)."}'::jsonb),
  ('l-a1-reading-day', 6, '{"type":"vocabulary","wordIds":["v-wake-up","v-breakfast","v-family"]}'::jsonb),
  ('l-a1-reading-day', 7, '{"type":"exercise","exerciseId":"ex-a1-reading-day"}'::jsonb),
  ('l-a1-present-continuous', 0, '{"type":"text","text":"Thì hiện tại tiếp diễn dùng để nói về việc đang xảy ra ngay lúc nói hoặc trong khoảng thời gian hiện tại."}'::jsonb),
  ('l-a1-present-continuous', 1, '{"type":"grammar","title":"Cấu trúc","structure":"S + am/is/are + V-ing  ·  S + am/is/are + not + V-ing  ·  Am/Is/Are + S + V-ing?","explanationVi":"Dấu hiệu: now, right now, at the moment, Look!, Listen!"}'::jsonb),
  ('l-a1-present-continuous', 2, '{"type":"example","en":"I''m cooking dinner right now.","vi":"Bây giờ tôi đang nấu bữa tối."}'::jsonb),
  ('l-a1-present-continuous', 3, '{"type":"example","en":"Look! It''s raining.","vi":"Nhìn kìa! Trời đang mưa."}'::jsonb),
  ('l-a1-present-continuous', 4, '{"type":"example","en":"Are you listening to me?","vi":"Bạn có đang nghe tôi nói không?"}'::jsonb),
  ('l-a1-present-continuous', 5, '{"type":"heading","text":"Chính tả V-ing"}'::jsonb),
  ('l-a1-present-continuous', 6, '{"type":"text","text":"Phần lớn động từ chỉ thêm -ing: read → reading. Động từ tận cùng bằng -e câm thì bỏ e: make → making, write → writing. Động từ một âm tiết kết thúc bằng phụ âm–nguyên âm–phụ âm thì gấp đôi phụ âm cuối: swim → swimming, sit → sitting. Tận cùng -ie đổi thành -y: lie → lying."}'::jsonb),
  ('l-a1-present-continuous', 7, '{"type":"heading","text":"Hiện tại tiếp diễn hay hiện tại đơn?"}'::jsonb),
  ('l-a1-present-continuous', 8, '{"type":"example","en":"She usually walks to work, but today she''s taking a taxi.","vi":"Cô ấy thường đi bộ đi làm (thói quen), nhưng hôm nay cô ấy đi taxi (đang diễn ra)."}'::jsonb),
  ('l-a1-present-continuous', 9, '{"type":"mistake","wrong":"I am knowing the answer.","right":"I know the answer.","explanationVi":"Động từ chỉ trạng thái như know, like, want, need, understand thường không dùng ở dạng tiếp diễn."}'::jsonb),
  ('l-a1-present-continuous', 10, '{"type":"mistake","wrong":"He watching TV now.","right":"He is watching TV now.","explanationVi":"Không được bỏ am/is/are. Tiếng Việt chỉ cần \"đang\", nhưng tiếng Anh cần cả \"be\" và V-ing."}'::jsonb),
  ('l-a1-present-continuous', 11, '{"type":"vocabulary","wordIds":["v-cook","v-study","v-watch","v-listen","v-read"]}'::jsonb),
  ('l-a1-present-continuous', 12, '{"type":"exercise","exerciseId":"ex-a1-present-continuous"}'::jsonb),
  ('l-a1-articles', 0, '{"type":"text","text":"Tiếng Việt không có mạo từ nên đây là điểm ngữ pháp người Việt hay sai. Hãy nhớ: chọn a/an dựa vào ÂM, không phải chữ cái."}'::jsonb),
  ('l-a1-articles', 1, '{"type":"grammar","title":"A / An","structure":"a + phụ âm  ·  an + nguyên âm (a, e, i, o, u)","explanationVi":"Dùng với danh từ đếm được số ít, khi nhắc đến lần đầu hoặc không xác định."}'::jsonb),
  ('l-a1-articles', 2, '{"type":"example","en":"a book, a university, a one-way ticket","vi":"\"university\" và \"one\" bắt đầu bằng âm phụ âm /j/ và /w/"}'::jsonb),
  ('l-a1-articles', 3, '{"type":"example","en":"an egg, an hour, an MBA","vi":"\"hour\" có \"h\" câm; \"MBA\" đọc là /em/"}'::jsonb),
  ('l-a1-articles', 4, '{"type":"grammar","title":"The","structure":"the + danh từ đã xác định","explanationVi":"Dùng khi người nghe biết bạn đang nói đến cái nào: đã nhắc trước đó, chỉ có một (the sun), hoặc rõ ngữ cảnh (the door)."}'::jsonb),
  ('l-a1-articles', 5, '{"type":"example","en":"I bought a laptop. The laptop is very fast.","vi":"Tôi đã mua một chiếc laptop. Chiếc laptop đó rất nhanh."}'::jsonb),
  ('l-a1-articles', 6, '{"type":"heading","text":"Không dùng mạo từ"}'::jsonb),
  ('l-a1-articles', 7, '{"type":"text","text":"Không dùng mạo từ với danh từ số nhiều hoặc không đếm được khi nói chung chung: I like music. Dogs are friendly."}'::jsonb),
  ('l-a1-articles', 8, '{"type":"mistake","wrong":"I am student.","right":"I am a student.","explanationVi":"Nghề nghiệp/danh từ đếm được số ít cần có a/an."}'::jsonb),
  ('l-a1-articles', 9, '{"type":"exercise","exerciseId":"ex-a1-articles"}'::jsonb),
  ('l-a1-plurals', 0, '{"type":"text","text":"Tiếng Việt dùng \"các, những\" để chỉ số nhiều, còn tiếng Anh thay đổi chính danh từ. Đừng quên đổi danh từ khi có từ hai trở lên!"}'::jsonb),
  ('l-a1-plurals', 1, '{"type":"grammar","title":"Quy tắc số nhiều","structure":"book → books  ·  box → boxes  ·  city → cities  ·  knife → knives","explanationVi":"Thêm -es sau -s, -sh, -ch, -x, -o (bus → buses, watch → watches, tomato → tomatoes). Phụ âm + y → -ies (baby → babies), nhưng nguyên âm + y chỉ thêm -s (day → days)."}'::jsonb),
  ('l-a1-plurals', 2, '{"type":"heading","text":"Số nhiều bất quy tắc"}'::jsonb),
  ('l-a1-plurals', 3, '{"type":"text","text":"man → men · woman → women · child → children · person → people · foot → feet · tooth → teeth · mouse → mice. Một số danh từ giữ nguyên: fish → fish, sheep → sheep."}'::jsonb),
  ('l-a1-plurals', 4, '{"type":"grammar","title":"This / that / these / those","structure":"gần: this + số ít, these + số nhiều  ·  xa: that + số ít, those + số nhiều","explanationVi":"Động từ phải hợp với danh từ: This book is… / These books are…"}'::jsonb),
  ('l-a1-plurals', 5, '{"type":"example","en":"This chair is comfortable, but those chairs are old.","vi":"Cái ghế này thoải mái, nhưng những cái ghế kia thì cũ."}'::jsonb),
  ('l-a1-plurals', 6, '{"type":"example","en":"Who are those people?","vi":"Những người kia là ai vậy?"}'::jsonb),
  ('l-a1-plurals', 7, '{"type":"mistake","wrong":"I have two childs.","right":"I have two children.","explanationVi":"\"Child\" có dạng số nhiều bất quy tắc là \"children\"."}'::jsonb),
  ('l-a1-plurals', 8, '{"type":"mistake","wrong":"These book is mine.","right":"This book is mine. / These books are mine.","explanationVi":"\"These\" đi với danh từ số nhiều và \"are\"."}'::jsonb),
  ('l-a1-plurals', 9, '{"type":"vocabulary","wordIds":["v-child","v-person","v-chair","v-table"]}'::jsonb),
  ('l-a1-plurals', 10, '{"type":"exercise","exerciseId":"ex-a1-plurals"}'::jsonb),
  ('l-a1-possessives', 0, '{"type":"grammar","title":"Tính từ sở hữu","structure":"I → my · you → your · he → his · she → her · it → its · we → our · they → their","explanationVi":"Đứng trước danh từ và không thay đổi theo số ít hay số nhiều: my friend, my friends."}'::jsonb),
  ('l-a1-possessives', 1, '{"type":"example","en":"This is my sister. Her name is Hoa.","vi":"Đây là em gái tôi. Tên em ấy là Hoa."}'::jsonb),
  ('l-a1-possessives', 2, '{"type":"grammar","title":"Sở hữu cách ''s","structure":"Người/vật sở hữu + ''s + danh từ","explanationVi":"Lan''s phone = điện thoại của Lan. Danh từ số nhiều tận cùng bằng -s chỉ thêm dấu '': my parents'' house."}'::jsonb),
  ('l-a1-possessives', 3, '{"type":"example","en":"My father''s car is black.","vi":"Ô tô của bố tôi màu đen.","note":"Thứ tự ngược với tiếng Việt: người sở hữu đứng trước."}'::jsonb),
  ('l-a1-possessives', 4, '{"type":"example","en":"Whose bag is this? — It''s Minh''s.","vi":"Cái túi này của ai? — Của Minh."}'::jsonb),
  ('l-a1-possessives', 5, '{"type":"mistake","wrong":"This is Lan phone.","right":"This is Lan''s phone.","explanationVi":"Cần thêm ''s sau người sở hữu."}'::jsonb),
  ('l-a1-possessives', 6, '{"type":"mistake","wrong":"The cat is eating it''s food.","right":"The cat is eating its food.","explanationVi":"\"its\" là tính từ sở hữu (của nó); \"it''s\" là viết tắt của \"it is\"."}'::jsonb),
  ('l-a1-possessives', 7, '{"type":"vocabulary","wordIds":["v-mother","v-father","v-sister","v-husband","v-wife"]}'::jsonb),
  ('l-a1-possessives', 8, '{"type":"exercise","exerciseId":"ex-a1-possessives"}'::jsonb),
  ('l-a1-there-is', 0, '{"type":"text","text":"Muốn nói ở đâu đó \"có\" cái gì, tiếng Anh dùng \"there is / there are\", không dùng \"have\"."}'::jsonb),
  ('l-a1-there-is', 1, '{"type":"grammar","title":"Cấu trúc","structure":"There is + danh từ số ít  ·  There are + danh từ số nhiều","explanationVi":"Phủ định: There isn''t / There aren''t. Câu hỏi: Is there…? / Are there…? Với số nhiều trong câu phủ định và câu hỏi thường dùng \"any\"."}'::jsonb),
  ('l-a1-there-is', 2, '{"type":"example","en":"There''s a big market near my house.","vi":"Gần nhà tôi có một cái chợ lớn."}'::jsonb),
  ('l-a1-there-is', 3, '{"type":"example","en":"There are three bedrooms in our flat.","vi":"Căn hộ của chúng tôi có ba phòng ngủ."}'::jsonb),
  ('l-a1-there-is', 4, '{"type":"example","en":"Is there a bank near here? — Yes, there is.","vi":"Gần đây có ngân hàng không? — Có."}'::jsonb),
  ('l-a1-there-is', 5, '{"type":"example","en":"There aren''t any parks in this area.","vi":"Khu này không có công viên nào."}'::jsonb),
  ('l-a1-there-is', 6, '{"type":"mistake","wrong":"Have a bank near here.","right":"There is a bank near here.","explanationVi":"\"Có\" chỉ sự tồn tại phải dịch là \"there is/are\". \"Have\" nghĩa là sở hữu: I have a car (tôi có ô tô)."}'::jsonb),
  ('l-a1-there-is', 7, '{"type":"mistake","wrong":"There is two cafés on this street.","right":"There are two cafés on this street.","explanationVi":"Danh từ số nhiều đi với \"there are\"."}'::jsonb),
  ('l-a1-there-is', 8, '{"type":"vocabulary","wordIds":["v-house","v-room","v-kitchen","v-park","v-market","v-bank"]}'::jsonb),
