  ('l-a1-prepositions-place', 0, '{"type":"grammar","title":"Giới từ thường gặp","structure":"in (trong) · on (trên, chạm bề mặt) · under (dưới) · next to (bên cạnh) · between A and B (giữa) · behind (sau) · in front of (trước) · opposite (đối diện)","explanationVi":"Giới từ đứng trước danh từ chỉ nơi chốn: on the table, under the bed."}'::jsonb),
  ('l-a1-prepositions-place', 1, '{"type":"example","en":"My keys are in my bag.","vi":"Chìa khoá của tôi ở trong túi."}'::jsonb),
  ('l-a1-prepositions-place', 2, '{"type":"example","en":"The phone is on the table.","vi":"Điện thoại ở trên bàn."}'::jsonb),
  ('l-a1-prepositions-place', 3, '{"type":"example","en":"The cat is sleeping under the bed.","vi":"Con mèo đang ngủ dưới gầm giường."}'::jsonb),
  ('l-a1-prepositions-place', 4, '{"type":"example","en":"The pharmacy is between the bank and the supermarket.","vi":"Hiệu thuốc nằm giữa ngân hàng và siêu thị."}'::jsonb),
  ('l-a1-prepositions-place', 5, '{"type":"example","en":"There is a café opposite my office.","vi":"Có một quán cà phê đối diện văn phòng tôi."}'::jsonb),
  ('l-a1-prepositions-place', 6, '{"type":"mistake","wrong":"The phone is in the table.","right":"The phone is on the table.","explanationVi":"\"In\" là bên trong một không gian; đồ vật đặt trên bề mặt dùng \"on\"."}'::jsonb),
  ('l-a1-prepositions-place', 7, '{"type":"tip","text":"Với các toà nhà, \"in front of\" là phía trước của cùng một toà; \"opposite\" là ở phía bên kia đường, đối diện."}'::jsonb),
  ('l-a1-prepositions-place', 8, '{"type":"vocabulary","wordIds":["v-table","v-bed","v-door","v-window","v-next-to","v-between","v-under","v-near"]}'::jsonb),
  ('l-a1-prepositions-place', 9, '{"type":"exercise","exerciseId":"ex-a1-prepositions-place"}'::jsonb),
  ('l-a1-can', 0, '{"type":"text","text":"\"Can\" nghĩa là \"có thể\" hoặc \"biết (làm gì)\". Đây là động từ khuyết thiếu nên dùng giống nhau với mọi chủ ngữ."}'::jsonb),
  ('l-a1-can', 1, '{"type":"grammar","title":"Cấu trúc","structure":"S + can / can''t + V (nguyên mẫu)  ·  Can + S + V?","explanationVi":"Không thêm -s cho \"can\" và không dùng \"to\" sau \"can\"."}'::jsonb),
  ('l-a1-can', 2, '{"type":"example","en":"I can swim, but I can''t drive.","vi":"Tôi biết bơi nhưng không biết lái xe."}'::jsonb),
  ('l-a1-can', 3, '{"type":"example","en":"Can you speak English? — Yes, a little.","vi":"Bạn nói được tiếng Anh không? — Có, một chút."}'::jsonb),
  ('l-a1-can', 4, '{"type":"example","en":"Can you help me, please?","vi":"Bạn giúp tôi được không?","note":"\"Could you…?\" lịch sự hơn \"Can you…?\"."}'::jsonb),
  ('l-a1-can', 5, '{"type":"tip","text":"Phát âm: trong câu khẳng định \"can\" thường đọc nhẹ /kən/, còn \"can''t\" đọc mạnh và rõ /kɑːnt/. Hãy nghe trọng âm để biết người nói có thể hay không thể."}'::jsonb),
  ('l-a1-can', 6, '{"type":"mistake","wrong":"I can to swim.","right":"I can swim.","explanationVi":"Sau \"can\" là động từ nguyên mẫu không có \"to\"."}'::jsonb),
  ('l-a1-can', 7, '{"type":"mistake","wrong":"She cans cook very well.","right":"She can cook very well.","explanationVi":"\"Can\" không thêm -s với he/she/it."}'::jsonb),
  ('l-a1-can', 8, '{"type":"vocabulary","wordIds":["v-swim","v-drive","v-cook","v-walk"]}'::jsonb),
  ('l-a1-can', 9, '{"type":"exercise","exerciseId":"ex-a1-can"}'::jsonb),
  ('l-a1-countable', 0, '{"type":"grammar","title":"Đếm được và không đếm được","structure":"Đếm được: an egg, two eggs  ·  Không đếm được: rice, bread, water, milk, money","explanationVi":"Danh từ không đếm được không có số nhiều và không đi với a/an. Muốn đếm, dùng đơn vị: a bowl of rice, two pieces of bread, a glass of water."}'::jsonb),
  ('l-a1-countable', 1, '{"type":"example","en":"I need two eggs and some milk.","vi":"Tôi cần hai quả trứng và một ít sữa."}'::jsonb),
  ('l-a1-countable', 2, '{"type":"grammar","title":"Some / any","structure":"Khẳng định: some  ·  Phủ định và câu hỏi: any","explanationVi":"Dùng được với cả danh từ không đếm được và danh từ đếm được số nhiều. Ngoại lệ: lời mời, lời đề nghị dùng \"some\": Would you like some tea?"}'::jsonb),
  ('l-a1-countable', 3, '{"type":"example","en":"There isn''t any bread, but there are some eggs.","vi":"Không còn bánh mì, nhưng còn vài quả trứng."}'::jsonb),
  ('l-a1-countable', 4, '{"type":"grammar","title":"Much / many","structure":"How many + danh từ đếm được số nhiều?  ·  How much + danh từ không đếm được?","explanationVi":"How many eggs? / How much rice?"}'::jsonb),
  ('l-a1-countable', 5, '{"type":"mistake","wrong":"I eat a rice every day.","right":"I eat rice every day.","explanationVi":"\"Rice\" không đếm được nên không dùng \"a\"."}'::jsonb),
  ('l-a1-countable', 6, '{"type":"mistake","wrong":"Can I have two breads?","right":"Can I have two pieces of bread?","explanationVi":"\"Bread\" không đếm được; dùng \"pieces/slices of bread\", hoặc gọi tên món cụ thể như \"two sandwiches\"."}'::jsonb),
  ('l-a1-countable', 7, '{"type":"vocabulary","wordIds":["v-rice","v-bread","v-egg","v-fruit","v-vegetable","v-milk"]}'::jsonb),
  ('l-a1-countable', 8, '{"type":"exercise","exerciseId":"ex-a1-countable"}'::jsonb),
  ('l-a1-ordering-food', 0, '{"type":"text","text":"Trong nhà hàng, cách nói lịch sự quan trọng hơn ngữ pháp phức tạp. Chỉ cần vài mẫu câu là bạn có thể gọi món tự tin."}'::jsonb),
  ('l-a1-ordering-food', 1, '{"type":"grammar","title":"Gọi món","structure":"I''d like + danh từ (, please).  ·  Can I have + danh từ, please?","explanationVi":"\"I''d like\" = \"I would like\", lịch sự hơn \"I want\". Thêm \"please\" ở cuối câu."}'::jsonb),
  ('l-a1-ordering-food', 2, '{"type":"example","en":"I''d like the grilled chicken, please.","vi":"Cho tôi món gà nướng."}'::jsonb),
  ('l-a1-ordering-food', 3, '{"type":"example","en":"Can I see the menu, please?","vi":"Cho tôi xem thực đơn được không?"}'::jsonb),
