  ('l-a1-shopping', 0, '{"type":"grammar","title":"Hỏi giá","structure":"How much is + danh từ số ít?  ·  How much are + danh từ số nhiều?","explanationVi":"Trả lời: It''s… / They''re… Không cần thêm \"money\" sau \"how much\"."}'::jsonb),
  ('l-a1-shopping', 1, '{"type":"example","en":"How much is this T-shirt? — It''s 150,000 dong.","vi":"Áo phông này bao nhiêu tiền? — 150.000 đồng.","note":"Đọc: one hundred and fifty thousand dong."}'::jsonb),
