  ('l-a1-shopping', 3, '{"type":"tip","text":"Tiếng Anh dùng dấu phẩy để ngăn cách hàng nghìn (150,000) và dấu chấm cho phần thập phân ($3.50 = three dollars fifty), ngược với cách viết ở Việt Nam."}'::jsonb),
