  ('l-a1-shopping', 7, '{"type":"mistake","wrong":"How much money is this shirt?","right":"How much is this shirt?","explanationVi":"Khi hỏi giá, \"how much\" đã đủ nghĩa."}'::jsonb),
  ('l-a1-shopping', 8, '{"type":"mistake","wrong":"How many water do you need?","right":"How much water do you need?","explanationVi":"\"Water\" không đếm được nên dùng \"how much\"."}'::jsonb),
