  ('l-a2-past-continuous', 0, '{"type":"text","text":"Khi kể chuyện, người bản ngữ dùng quá khứ tiếp diễn để \"dựng cảnh\" (việc đang diễn ra), rồi dùng quá khứ đơn cho sự việc chính xảy ra."}'::jsonb),
  ('l-a2-past-continuous', 1, '{"type":"grammar","title":"Cấu trúc","structure":"I/he/she/it + was + V-ing  ·  you/we/they + were + V-ing","explanationVi":"Phủ định: wasn''t / weren''t + V-ing. Câu hỏi: Was/Were + S + V-ing?"}'::jsonb),
  ('l-a2-past-continuous', 2, '{"type":"example","en":"At 8 p.m. yesterday, I was watching a film.","vi":"Lúc 8 giờ tối qua, tôi đang xem phim."}'::jsonb),
