  ('l-a2-past-continuous', 4, '{"type":"example","en":"I was cooking dinner when the phone rang.","vi":"Tôi đang nấu bữa tối thì điện thoại reo."}'::jsonb),
  ('l-a2-past-continuous', 5, '{"type":"example","en":"While we were walking home, it suddenly started to rain.","vi":"Khi chúng tôi đang đi bộ về nhà thì trời đột nhiên đổ mưa."}'::jsonb),
  ('l-a2-past-continuous', 6, '{"type":"mistake","wrong":"While I walked home, it started to rain.","right":"While I was walking home, it started to rain.","explanationVi":"Hành động kéo dài làm bối cảnh cần dạng tiếp diễn."}'::jsonb),
  ('l-a2-past-continuous', 7, '{"type":"mistake","wrong":"When I was walking, it was starting to rain.","right":"When I was walking, it started to rain.","explanationVi":"Sự việc ngắn, đột ngột xen vào dùng quá khứ đơn."}'::jsonb),
