  ('l-a2-future-arrangements', 1, '{"type":"example","en":"I''m meeting my manager at 10 tomorrow.","vi":"Tôi có hẹn gặp quản lý lúc 10 giờ ngày mai."}'::jsonb),
  ('l-a2-future-arrangements', 2, '{"type":"example","en":"What are you doing this weekend?","vi":"Cuối tuần này bạn định làm gì?"}'::jsonb),
  ('l-a2-future-arrangements', 3, '{"type":"grammar","title":"Lịch trình cố định","structure":"S + V (hiện tại đơn) + thời gian","explanationVi":"Dùng cho giờ tàu, xe, phim, lớp học… theo thời gian biểu."}'::jsonb),
  ('l-a2-future-arrangements', 4, '{"type":"example","en":"The train to Hai Phong leaves at 6:15 tomorrow morning.","vi":"Tàu đi Hải Phòng khởi hành lúc 6 giờ 15 sáng mai."}'::jsonb),
  ('l-a2-future-arrangements', 5, '{"type":"example","en":"The film starts at 8 p.m.","vi":"Phim bắt đầu lúc 8 giờ tối."}'::jsonb),
  ('l-a2-future-arrangements', 6, '{"type":"mistake","wrong":"I meet my friends tonight at 7.","right":"I''m meeting my friends tonight at 7.","explanationVi":"Kế hoạch cá nhân đã hẹn trước dùng hiện tại tiếp diễn (hoặc \"going to\"), không dùng hiện tại đơn."}'::jsonb),
  ('l-a2-future-arrangements', 7, '{"type":"tip","text":"Tóm tắt: lịch hẹn → am/is/are + V-ing · ý định → going to · quyết định tức thì → will · thời gian biểu → hiện tại đơn."}'::jsonb),
  ('l-a2-future-arrangements', 8, '{"type":"vocabulary","wordIds":["v-appointment","v-arrange","v-weekend","v-busy"]}'::jsonb),
  ('l-a2-future-arrangements', 9, '{"type":"exercise","exerciseId":"ex-a2-future-arrangements"}'::jsonb),
  ('l-a2-invitations', 0, '{"type":"grammar","title":"Gợi ý","structure":"Let''s + V  ·  Why don''t we + V?  ·  How about + V-ing?","explanationVi":"Ba cách đều có nghĩa \"mình… nhé?\". Chú ý dạng động từ theo sau mỗi cấu trúc."}'::jsonb),
  ('l-a2-invitations', 1, '{"type":"example","en":"Let''s go to the beach this weekend.","vi":"Cuối tuần này mình đi biển nhé."}'::jsonb),
  ('l-a2-invitations', 2, '{"type":"example","en":"How about having dinner at the new Korean place?","vi":"Hay mình ăn tối ở quán Hàn mới mở nhé?"}'::jsonb),
  ('l-a2-invitations', 3, '{"type":"grammar","title":"Lời mời","structure":"Would you like + to V?  ·  Would you like + danh từ?","explanationVi":"Lịch sự hơn \"Do you want…?\"."}'::jsonb),
  ('l-a2-invitations', 4, '{"type":"example","en":"Would you like to come to my birthday party?","vi":"Bạn có muốn đến dự tiệc sinh nhật của tôi không?"}'::jsonb),
  ('l-a2-invitations', 5, '{"type":"heading","text":"Nhận lời và từ chối"}'::jsonb),
  ('l-a2-invitations', 6, '{"type":"example","en":"That sounds great! / I''d love to.","vi":"Nghe hay đấy! / Mình rất muốn."}'::jsonb),
  ('l-a2-invitations', 7, '{"type":"example","en":"I''d love to, but I''m afraid I''m busy on Saturday.","vi":"Mình rất muốn, nhưng tiếc là thứ Bảy mình bận.","note":"Khi từ chối, hãy cảm ơn và đưa lý do ngắn gọn."}'::jsonb),
  ('l-a2-invitations', 8, '{"type":"mistake","wrong":"How about go to the cinema?","right":"How about going to the cinema?","explanationVi":"Sau \"How about\" dùng V-ing."}'::jsonb),
  ('l-a2-invitations', 9, '{"type":"mistake","wrong":"Let''s to go out tonight.","right":"Let''s go out tonight.","explanationVi":"Sau \"Let''s\" là động từ nguyên mẫu không \"to\"."}'::jsonb),
  ('l-a2-invitations', 10, '{"type":"vocabulary","wordIds":["v-invite","v-free-time","v-busy","v-probably"]}'::jsonb),
  ('l-a2-invitations', 11, '{"type":"exercise","exerciseId":"ex-a2-invitations"}'::jsonb),
  ('l-a2-comparatives', 0, '{"type":"grammar","title":"Tính từ ngắn","structure":"adj + -er + than","explanationVi":"cheap → cheaper; big → bigger (gấp đôi phụ âm); busy → busier (y → ier); nice → nicer."}'::jsonb),
  ('l-a2-comparatives', 1, '{"type":"grammar","title":"Tính từ dài (từ 2 âm tiết, trừ đuôi -y)","structure":"more + adj + than","explanationVi":"comfortable → more comfortable; modern → more modern."}'::jsonb),
  ('l-a2-comparatives', 2, '{"type":"grammar","title":"Bất quy tắc","structure":"good → better · bad → worse · far → further/farther","explanationVi":"Cần học thuộc."}'::jsonb),
  ('l-a2-comparatives', 3, '{"type":"example","en":"Da Lat is cooler and quieter than Ho Chi Minh City.","vi":"Đà Lạt mát và yên tĩnh hơn Thành phố Hồ Chí Minh."}'::jsonb),
  ('l-a2-comparatives', 4, '{"type":"example","en":"This flat is more comfortable than our old one.","vi":"Căn hộ này thoải mái hơn căn cũ của chúng tôi."}'::jsonb),
  ('l-a2-comparatives', 5, '{"type":"example","en":"My English is getting better.","vi":"Tiếng Anh của tôi đang tốt dần lên."}'::jsonb),
  ('l-a2-comparatives', 6, '{"type":"grammar","title":"So sánh bằng","structure":"as + adj + as  ·  not as + adj + as","explanationVi":"Lan is as tall as her brother (cao bằng). The bus isn''t as fast as the train (xe buýt không nhanh bằng tàu)."}'::jsonb),
  ('l-a2-comparatives', 7, '{"type":"mistake","wrong":"My phone is more cheaper than yours.","right":"My phone is cheaper than yours.","explanationVi":"Không dùng \"more\" cùng với đuôi \"-er\"."}'::jsonb),
  ('l-a2-comparatives', 8, '{"type":"vocabulary","wordIds":["v-comfortable","v-crowded","v-quiet","v-noisy","v-modern"]}'::jsonb),
  ('l-a2-comparatives', 9, '{"type":"exercise","exerciseId":"ex-a2-comparatives"}'::jsonb),
  ('l-a2-superlatives', 0, '{"type":"grammar","title":"Cấu trúc","structure":"the + adj-est  ·  the most + adj (dài)  ·  the best / the worst","explanationVi":"Luôn có \"the\". Sau so sánh nhất: \"in\" + nơi chốn/nhóm (in Vietnam, in my class), \"of\" + khoảng thời gian/số lượng (of the year, of all)."}'::jsonb),
  ('l-a2-superlatives', 1, '{"type":"example","en":"Fansipan is the highest mountain in Vietnam.","vi":"Fansipan là ngọn núi cao nhất Việt Nam."}'::jsonb),
  ('l-a2-superlatives', 2, '{"type":"example","en":"Tet is the most important holiday of the year.","vi":"Tết là ngày lễ quan trọng nhất trong năm."}'::jsonb),
  ('l-a2-superlatives', 3, '{"type":"example","en":"She''s the friendliest person in our office.","vi":"Cô ấy là người thân thiện nhất văn phòng chúng tôi."}'::jsonb),
  ('l-a2-superlatives', 4, '{"type":"mistake","wrong":"He is the most fast runner in the team.","right":"He is the fastest runner in the team.","explanationVi":"Tính từ ngắn dùng đuôi \"-est\", không dùng \"most\"."}'::jsonb),
  ('l-a2-superlatives', 5, '{"type":"mistake","wrong":"This is the better restaurant in town.","right":"This is the best restaurant in town.","explanationVi":"So sánh trong một nhóm lớn hơn hai dùng so sánh nhất \"the best\"."}'::jsonb),
  ('l-a2-superlatives', 6, '{"type":"vocabulary","wordIds":["v-traditional","v-dangerous","v-safe","v-friendly"]}'::jsonb),
  ('l-a2-superlatives', 7, '{"type":"exercise","exerciseId":"ex-a2-superlatives"}'::jsonb),
  ('l-a2-obligation', 0, '{"type":"grammar","title":"Bắt buộc","structure":"must + V  ·  have to / has to + V","explanationVi":"\"Must\" thường thể hiện ý kiến của người nói; \"have to\" thường nói về quy định bên ngoài. Ở mức A2, cả hai đều nghĩa là \"phải\"."}'::jsonb),
  ('l-a2-obligation', 1, '{"type":"example","en":"Students have to wear a uniform.","vi":"Học sinh phải mặc đồng phục."}'::jsonb),
  ('l-a2-obligation', 2, '{"type":"example","en":"I must call my mother tonight.","vi":"Tối nay tôi phải gọi cho mẹ."}'::jsonb),
  ('l-a2-obligation', 3, '{"type":"grammar","title":"Mustn''t và don''t have to","structure":"mustn''t + V = không được phép  ·  don''t have to + V = không cần","explanationVi":"Hai cấu trúc này có nghĩa rất khác nhau dù đều ở dạng phủ định."}'::jsonb),
  ('l-a2-obligation', 4, '{"type":"example","en":"You mustn''t smoke here.","vi":"Bạn không được hút thuốc ở đây."}'::jsonb),
  ('l-a2-obligation', 5, '{"type":"example","en":"It''s Sunday, so I don''t have to get up early.","vi":"Hôm nay Chủ nhật nên tôi không cần dậy sớm."}'::jsonb),
  ('l-a2-obligation', 6, '{"type":"grammar","title":"Lời khuyên","structure":"should / shouldn''t + V","explanationVi":"Nhẹ nhàng hơn \"must\"."}'::jsonb),
  ('l-a2-obligation', 7, '{"type":"example","en":"You have a headache. You should take some medicine and rest.","vi":"Bạn bị đau đầu. Bạn nên uống thuốc và nghỉ ngơi."}'::jsonb),
  ('l-a2-obligation', 8, '{"type":"mistake","wrong":"You should to see a doctor.","right":"You should see a doctor.","explanationVi":"\"Should\" và \"must\" là động từ khuyết thiếu: theo sau là V nguyên mẫu không \"to\". Riêng \"have to\" luôn có \"to\"."}'::jsonb),
  ('l-a2-obligation', 9, '{"type":"mistake","wrong":"You don''t have to smoke in the hospital.","right":"You mustn''t smoke in the hospital.","explanationVi":"Muốn nói \"cấm\" phải dùng \"mustn''t\"."}'::jsonb),
  ('l-a2-obligation', 10, '{"type":"vocabulary","wordIds":["v-rule","v-uniform","v-headache","v-medicine","v-healthy","v-exercise"]}'::jsonb),
  ('l-a2-obligation', 11, '{"type":"exercise","exerciseId":"ex-a2-obligation"}'::jsonb),
  ('l-b1-present-perfect', 0, '{"type":"grammar","title":"Hiện tại hoàn thành","structure":"S + have/has + V3","explanationVi":"Nối quá khứ với hiện tại: trải nghiệm (ever/never), hành động kéo dài đến nay (for/since), kết quả còn ảnh hưởng (just/already/yet)."}'::jsonb),
  ('l-b1-present-perfect', 1, '{"type":"example","en":"I''ve worked as a developer for five years.","vi":"Tôi đã làm lập trình viên được năm năm (và vẫn đang làm)."}'::jsonb),
  ('l-b1-present-perfect', 2, '{"type":"example","en":"Have you ever been to Japan?","vi":"Bạn đã từng đến Nhật chưa?"}'::jsonb),
  ('l-b1-present-perfect', 3, '{"type":"grammar","title":"Quá khứ đơn","structure":"S + V2/-ed + mốc thời gian đã kết thúc","explanationVi":"Khi có thời điểm cụ thể (yesterday, in 2022, last week), dùng quá khứ đơn."}'::jsonb),
  ('l-b1-present-perfect', 4, '{"type":"example","en":"I went to Japan in 2022.","vi":"Tôi đã đến Nhật vào năm 2022."}'::jsonb),
  ('l-b1-present-perfect', 5, '{"type":"tip","text":"Mẹo: nếu bạn có thể trả lời câu hỏi \"Khi nào?\" bằng một thời điểm cụ thể đã qua → dùng quá khứ đơn."}'::jsonb),
  ('l-b1-present-perfect', 6, '{"type":"mistake","wrong":"I have met him last week.","right":"I met him last week.","explanationVi":"\"Last week\" là mốc thời gian đã kết thúc."}'::jsonb),
  ('l-b1-present-perfect', 7, '{"type":"vocabulary","wordIds":["v-experience","v-improve","v-confident"]}'::jsonb),
  ('l-b1-present-perfect', 8, '{"type":"exercise","exerciseId":"ex-b1-present-perfect"}'::jsonb),
  ('l-b1-standup', 0, '{"type":"text","text":"Daily stand-up thường chỉ kéo dài 10–15 phút. Mỗi người trả lời ba câu hỏi: Hôm qua làm gì? Hôm nay làm gì? Có gì cản trở không?"}'::jsonb),
  ('l-b1-standup', 1, '{"type":"grammar","title":"Khung báo cáo","structure":"Yesterday I + V2 …  ·  Today I''m going to + V …  ·  I''m blocked on … / No blockers.","explanationVi":"Dùng quá khứ đơn cho việc đã làm, \"going to\" cho kế hoạch hôm nay."}'::jsonb),
  ('l-b1-standup', 2, '{"type":"example","en":"Yesterday I fixed the bug in the checkout flow and wrote some tests.","vi":"Hôm qua tôi đã sửa lỗi ở luồng thanh toán và viết một số test."}'::jsonb),
  ('l-b1-standup', 3, '{"type":"example","en":"Today I''m going to work on the search API.","vi":"Hôm nay tôi sẽ làm API tìm kiếm."}'::jsonb),
  ('l-b1-standup', 4, '{"type":"example","en":"I''m blocked on the deployment — I don''t have access to the staging server yet.","vi":"Tôi đang bị kẹt ở bước triển khai — tôi chưa có quyền truy cập server staging."}'::jsonb),
  ('l-b1-standup', 5, '{"type":"tip","text":"Đừng đi vào chi tiết kỹ thuật dài dòng trong stand-up. Hãy nói: \"Let''s take this offline\" (mình trao đổi riêng sau nhé)."}'::jsonb),
  ('l-b1-standup', 6, '{"type":"mistake","wrong":"Yesterday I do the login page.","right":"Yesterday I worked on the login page.","explanationVi":"Việc hôm qua phải dùng quá khứ. \"Work on\" tự nhiên hơn \"do\" khi nói về một tính năng."}'::jsonb),
  ('l-b1-standup', 7, '{"type":"vocabulary","wordIds":["v-blocker","v-deadline","v-deploy","v-colleague"]}'::jsonb),
  ('l-b1-standup', 8, '{"type":"exercise","exerciseId":"ex-b1-standup"}'::jsonb),
  ('l-b1-code-review', 0, '{"type":"text","text":"Bình luận code review tốt tập trung vào code, không phải con người. Hãy đề xuất cụ thể và nêu lý do."}'::jsonb),
  ('l-b1-code-review', 1, '{"type":"grammar","title":"Cách góp ý nhẹ nhàng","structure":"Could we …?  ·  What do you think about …?  ·  Consider + V-ing …","explanationVi":"Dạng câu hỏi và \"we\" tạo cảm giác hợp tác thay vì chỉ trích."}'::jsonb),
  ('l-b1-code-review', 2, '{"type":"example","en":"Could we rename this variable to make its purpose clearer?","vi":"Mình đổi tên biến này cho rõ mục đích hơn được không?"}'::jsonb),
  ('l-b1-code-review', 3, '{"type":"example","en":"nit: there is an extra blank line here.","vi":"Góp ý nhỏ: chỗ này thừa một dòng trống."}'::jsonb),
  ('l-b1-code-review', 4, '{"type":"example","en":"Nice refactor! This is much easier to read.","vi":"Refactor hay đấy! Dễ đọc hơn nhiều."}'::jsonb),
  ('l-b1-code-review', 5, '{"type":"mistake","wrong":"You must change this.","right":"I think we should change this because it may cause a race condition.","explanationVi":"\"Must\" nghe như ra lệnh. Thêm lý do giúp người nhận hiểu và đồng ý dễ hơn."}'::jsonb),
  ('l-b1-code-review', 6, '{"type":"vocabulary","wordIds":["v-review","v-bug","v-improve"]}'::jsonb),
  ('l-b1-code-review', 7, '{"type":"exercise","exerciseId":"ex-b1-code-review"}'::jsonb),
  ('l-b2-conditionals', 0, '{"type":"grammar","title":"Loại 2 — không có thật ở hiện tại","structure":"If + S + V2, S + would/could + V","explanationVi":"Với \"to be\", dùng \"were\" cho mọi chủ ngữ trong văn phong chuẩn: If I were you..."}'::jsonb),
  ('l-b2-conditionals', 1, '{"type":"example","en":"If I lived closer to the office, I would cycle to work.","vi":"Nếu tôi sống gần văn phòng hơn, tôi sẽ đạp xe đi làm (thực tế là không sống gần)."}'::jsonb),
  ('l-b2-conditionals', 2, '{"type":"grammar","title":"Loại 3 — không có thật trong quá khứ","structure":"If + S + had + V3, S + would have + V3","explanationVi":"Thường dùng để nói về hối tiếc hoặc phân tích nguyên nhân."}'::jsonb),
  ('l-b2-conditionals', 3, '{"type":"example","en":"If we had load-tested the service, it wouldn''t have crashed.","vi":"Nếu chúng ta đã kiểm thử tải dịch vụ thì nó đã không bị sập."}'::jsonb),
  ('l-b2-conditionals', 4, '{"type":"grammar","title":"Hỗn hợp","structure":"If + had V3 (quá khứ), would + V (hiện tại)","explanationVi":"Nguyên nhân trong quá khứ dẫn đến kết quả ở hiện tại."}'::jsonb),
  ('l-b2-conditionals', 5, '{"type":"example","en":"If I had accepted that job, I would be living in Singapore now.","vi":"Nếu hồi đó tôi nhận công việc ấy thì giờ tôi đang sống ở Singapore."}'::jsonb),
  ('l-b2-conditionals', 6, '{"type":"mistake","wrong":"If I would have known, I would have told you.","right":"If I had known, I would have told you.","explanationVi":"Không dùng \"would\" trong mệnh đề \"if\"."}'::jsonb),
  ('l-b2-conditionals', 7, '{"type":"vocabulary","wordIds":["v-regret","v-trade-off","v-negotiate"]}'::jsonb),
  ('l-b2-conditionals', 8, '{"type":"exercise","exerciseId":"ex-b2-conditionals"}'::jsonb),
  ('l-c1-inversion', 0, '{"type":"text","text":"Đảo ngữ làm câu văn trang trọng và nhấn mạnh hơn. Nó phổ biến trong bài phát biểu, báo chí và văn học, nhưng hiếm trong hội thoại thân mật."}'::jsonb),
  ('l-c1-inversion', 1, '{"type":"grammar","title":"Cấu trúc chung","structure":"Trạng từ phủ định + trợ động từ + S + V","explanationVi":"Các từ thường gặp: never, rarely, seldom, hardly, scarcely, not only, not until, under no circumstances, little."}'::jsonb),
  ('l-c1-inversion', 2, '{"type":"example","en":"Rarely do we see such dedication.","vi":"Hiếm khi chúng ta thấy sự tận tâm như vậy."}'::jsonb),
  ('l-c1-inversion', 3, '{"type":"example","en":"Under no circumstances should you share your password.","vi":"Trong bất kỳ trường hợp nào bạn cũng không được chia sẻ mật khẩu."}'::jsonb),
  ('l-c1-inversion', 4, '{"type":"example","en":"Hardly had I logged in when the system crashed.","vi":"Tôi vừa đăng nhập thì hệ thống sập."}'::jsonb),
  ('l-c1-inversion', 5, '{"type":"mistake","wrong":"Not until the meeting ended we realised the mistake.","right":"Not until the meeting ended did we realise the mistake.","explanationVi":"Với \"Not until\", đảo ngữ xảy ra ở mệnh đề chính, không phải mệnh đề đi sau \"until\"."}'::jsonb),
  ('l-c1-inversion', 6, '{"type":"vocabulary","wordIds":["v-scarcely","v-mitigate","v-nuance"]}'::jsonb),
  ('l-c1-inversion', 7, '{"type":"exercise","exerciseId":"ex-c1-inversion"}'::jsonb),
  ('l-c2-cleft', 0, '{"type":"text","text":"Câu chẻ \"chẻ\" một câu đơn thành hai phần để đưa thông tin quan trọng vào vị trí nổi bật. Người bản ngữ dùng chúng rất tự nhiên khi sửa lại hiểu lầm hoặc nhấn mạnh ý chính."}'::jsonb),
  ('l-c2-cleft', 1, '{"type":"grammar","title":"It-cleft","structure":"It + be + [thông tin nhấn mạnh] + that/who + …","explanationVi":"Thường dùng để đối chiếu: nhấn mạnh \"chính là X chứ không phải Y\"."}'::jsonb),
  ('l-c2-cleft', 2, '{"type":"example","en":"It was the caching layer that slowed everything down, not the database.","vi":"Chính lớp cache mới là thứ làm mọi thứ chậm lại, không phải cơ sở dữ liệu."}'::jsonb),
  ('l-c2-cleft', 3, '{"type":"grammar","title":"Wh-cleft (pseudo-cleft)","structure":"What + S + V + be + [thông tin nhấn mạnh]","explanationVi":"Dẫn dắt người nghe đến điểm chính, thường đặt ở cuối câu."}'::jsonb),
  ('l-c2-cleft', 4, '{"type":"example","en":"What really matters is how users feel about the product.","vi":"Điều thực sự quan trọng là người dùng cảm thấy thế nào về sản phẩm."}'::jsonb),
  ('l-c2-cleft', 5, '{"type":"example","en":"All I want is a straight answer.","vi":"Tất cả những gì tôi muốn là một câu trả lời thẳng thắn."}'::jsonb),
  ('l-c2-cleft', 6, '{"type":"mistake","wrong":"What I need it is more time.","right":"What I need is more time.","explanationVi":"Mệnh đề \"What I need\" đã là chủ ngữ, không thêm \"it\"."}'::jsonb),
  ('l-c2-cleft', 7, '{"type":"vocabulary","wordIds":["v-ubiquitous","v-equivocal","v-nuance"]}'::jsonb),
  ('l-c2-cleft', 8, '{"type":"exercise","exerciseId":"ex-c2-cleft"}'::jsonb)
insert into public.grammar_topics (id, level_id, title, title_vi, summary_vi, lesson_id, sort_order) values
  ('g-to-be', 'A1', 'The verb "to be"', 'Động từ "to be"', 'am / is / are: khẳng định, phủ định, câu hỏi.', 'l-a1-to-be', 1),
  ('g-present-simple', 'A1', 'Present simple', 'Thì hiện tại đơn', 'Thói quen, sự thật; thêm -s/-es với he/she/it; do/does.', 'l-a1-present-simple', 2),
  ('g-present-continuous', 'A1', 'Present continuous', 'Thì hiện tại tiếp diễn', 'am/is/are + V-ing cho việc đang diễn ra.', 'l-a1-present-continuous', 3),
  ('g-articles', 'A1', 'Articles: a, an, the', 'Mạo từ a, an, the', 'Chọn a/an theo âm đầu; the cho thứ đã xác định.', 'l-a1-articles', 4),
