  ('g-there-is', 'A1', 'There is / there are', 'There is / there are', 'Diễn tả "có" (tồn tại) — không dùng "have".', 'l-a1-there-is', 7),
  ('g-prepositions-place', 'A1', 'Prepositions of place', 'Giới từ chỉ vị trí', 'in, on, under, next to, between, opposite…', 'l-a1-prepositions-place', 8),
  ('g-can', 'A1', 'Can / can''t', 'Can / can''t', 'Khả năng, xin phép, nhờ vả; can + V nguyên mẫu.', 'l-a1-can', 9),
  ('g-countable', 'A1', 'Countable & uncountable nouns', 'Danh từ đếm được / không đếm được', 'some, any, much, many; a glass of, a bowl of.', 'l-a1-countable', 10),
  ('g-past-simple', 'A2', 'Past simple', 'Thì quá khứ đơn', 'V-ed và động từ bất quy tắc; did / didn''t.', 'l-a2-past-simple', 1),
  ('g-past-continuous', 'A2', 'Past continuous', 'Thì quá khứ tiếp diễn', 'was/were + V-ing; when và while.', 'l-a2-past-continuous', 2),
  ('g-used-to', 'A2', 'Used to', 'Used to', 'Thói quen, trạng thái trong quá khứ nay không còn.', 'l-a2-used-to', 3),
  ('g-future', 'A2', 'Be going to vs will', 'Be going to và will', 'Ý định có trước, quyết định tức thì và dự đoán.', 'l-a2-future', 4),
  ('g-future-arrangements', 'A2', 'Present tenses for the future', 'Thì hiện tại nói về tương lai', 'Hiện tại tiếp diễn cho lịch hẹn; hiện tại đơn cho thời gian biểu.', 'l-a2-future-arrangements', 5),
  ('g-suggestions', 'A2', 'Suggestions & invitations', 'Câu gợi ý và lời mời', 'Let''s + V, How about + V-ing, Would you like + to V.', 'l-a2-invitations', 6),
  ('g-comparatives', 'A2', 'Comparatives', 'So sánh hơn', '-er / more … than; better, worse; as … as.', 'l-a2-comparatives', 7),
  ('g-superlatives', 'A2', 'Superlatives', 'So sánh nhất', 'the -est / the most; the best, the worst.', 'l-a2-superlatives', 8),
