  ('ex-a1-prepositions-place', 'A1', 'grammar', 'Prepositions of place', 'Giới từ chỉ vị trí', 'in, on, under, next to, between…', 4),
  ('ex-a1-can', 'A1', 'grammar', 'Can and can''t', 'Can và can''t', 'Khả năng và lời nhờ vả.', 4),
  ('ex-a1-countable', 'A1', 'grammar', 'Some, any, much, many', 'Some, any, much, many', 'Danh từ đếm được và không đếm được.', 4),
  ('ex-a1-ordering-food', 'A1', 'vocabulary', 'At a restaurant', 'Ở nhà hàng', 'Gọi món và thanh toán lịch sự.', 4),
  ('ex-a1-shopping', 'A1', 'vocabulary', 'Shopping', 'Mua sắm', 'Hỏi giá, nói giá và thanh toán.', 4),
  ('ex-a2-past-continuous', 'A2', 'grammar', 'Past continuous', 'Quá khứ tiếp diễn', 'was/were + V-ing, when và while.', 5),
  ('ex-a2-used-to', 'A2', 'grammar', 'Used to', 'Used to', 'Thói quen và trạng thái trong quá khứ.', 4),
  ('ex-a2-reading-trip', 'A2', 'reading', 'Reading: A trip to Sa Pa', 'Đọc hiểu: Chuyến đi Sa Pa', 'Đọc câu chuyện và trả lời câu hỏi.', 6),
  ('ex-a2-future-arrangements', 'A2', 'grammar', 'Arrangements & timetables', 'Lịch hẹn & thời gian biểu', 'Hiện tại tiếp diễn và hiện tại đơn cho tương lai.', 4),
  ('ex-a2-invitations', 'A2', 'vocabulary', 'Suggestions & invitations', 'Rủ rê và mời mọc', 'Let''s, How about, Would you like…?', 4),
  ('ex-a2-comparatives', 'A2', 'grammar', 'Comparatives', 'So sánh hơn', '-er, more, better, as … as.', 4),
  ('ex-a2-superlatives', 'A2', 'grammar', 'Superlatives', 'So sánh nhất', 'the -est, the most, the best.', 4),
  ('ex-a2-obligation', 'A2', 'grammar', 'Must, have to, should', 'Must, have to, should', 'Bắt buộc, cấm, không cần và lời khuyên.', 5)
insert into public.questions (id, exercise_id, position, type, prompt, context, payload, explanation_vi) values
  ('ex-a1-greetings:q1', 'ex-a1-greetings', 0, 'multiple_choice', 'Someone says "Nice to meet you." What is the best reply?', null, '{}'::jsonb, 'Đáp lại "Nice to meet you" một cách tự nhiên nhất là "Nice to meet you, too" (Tôi cũng rất vui được gặp bạn).'),
  ('ex-a1-greetings:q2', 'ex-a1-greetings', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"What ___ your name?","acceptedAnswers":["is","''s"]}'::jsonb, '"Name" là danh từ số ít nên dùng "is": What is your name?'),
  ('ex-a1-greetings:q3', 'ex-a1-greetings', 2, 'matching', 'Nối câu hỏi với câu trả lời phù hợp.', null, '{"pairs":[{"left":"How are you?","right":"I''m fine, thanks."},{"left":"Where are you from?","right":"I''m from Vietnam."},{"left":"What do you do?","right":"I''m a developer."}]}'::jsonb, '"How are you?" hỏi thăm sức khoẻ, "Where are you from?" hỏi quê quán, "What do you do?" hỏi nghề nghiệp.'),
  ('ex-a1-greetings:q4', 'ex-a1-greetings', 3, 'ordering', 'Sắp xếp các từ thành câu đúng.', null, '{"tokens":["I","am","from","Ho Chi Minh City"]}'::jsonb, 'Cấu trúc: Chủ ngữ + am/is/are + from + địa danh.'),
  ('ex-a1-greetings:q5', 'ex-a1-greetings', 4, 'true_false', 'Câu sau dùng đúng hay sai?', null, '{"statement":"\"Good night\" is a greeting you use when you meet someone in the evening.","answer":false}'::jsonb, '"Good night" dùng khi chào tạm biệt hoặc trước khi đi ngủ. Khi gặp ai đó buổi tối ta nói "Good evening".'),
  ('ex-a1-to-be:q1', 'ex-a1-to-be', 0, 'multiple_choice', 'They ___ students.', null, '{}'::jsonb, '"They" là chủ ngữ số nhiều nên đi với "are".'),
  ('ex-a1-to-be:q2', 'ex-a1-to-be', 1, 'fill_blank', 'Điền dạng đúng của "to be".', null, '{"sentence":"My sister ___ a nurse.","acceptedAnswers":["is"]}'::jsonb, '"My sister" = she (ngôi thứ ba số ít) → "is".'),
  ('ex-a1-to-be:q3', 'ex-a1-to-be', 2, 'error_correction', 'Câu sau có một lỗi sai. Hãy viết lại câu đúng.', null, '{"sentence":"I is very happy today.","acceptedAnswers":["I am very happy today.","I''m very happy today."]}'::jsonb, 'Chủ ngữ "I" luôn đi với "am", không dùng "is".'),
  ('ex-a1-to-be:q4', 'ex-a1-to-be', 3, 'multiple_choice', 'Chọn câu phủ định đúng.', null, '{}'::jsonb, 'Phủ định của "to be": thêm "not" sau động từ → is not = isn''t.'),
  ('ex-a1-to-be:q5', 'ex-a1-to-be', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Chúng tôi là bạn bè.","acceptedAnswers":["We are friends.","We''re friends."]}'::jsonb, '"Chúng tôi" = we → we are; "bạn bè" ở số nhiều = friends.'),
  ('ex-a1-to-be:q6', 'ex-a1-to-be', 5, 'ordering', 'Sắp xếp thành câu hỏi đúng.', null, '{"tokens":["Are","you","a","teacher","?"]}'::jsonb, 'Câu hỏi Yes/No với "to be": đưa am/is/are lên trước chủ ngữ.'),
  ('ex-a1-present-simple:q1', 'ex-a1-present-simple', 0, 'multiple_choice', 'She ___ to work by bus.', null, '{}'::jsonb, 'Với he/she/it, động từ kết thúc bằng -o thêm "-es": go → goes.'),
  ('ex-a1-present-simple:q2', 'ex-a1-present-simple', 1, 'fill_blank', 'Điền trợ động từ đúng.', null, '{"sentence":"___ you like coffee?","acceptedAnswers":["Do"]}'::jsonb, 'Câu hỏi với "you" dùng trợ động từ "Do".'),
  ('ex-a1-present-simple:q3', 'ex-a1-present-simple', 2, 'error_correction', 'Sửa lỗi sai trong câu.', null, '{"sentence":"He don''t watch TV in the morning.","acceptedAnswers":["He doesn''t watch TV in the morning.","He does not watch TV in the morning."]}'::jsonb, 'Với he/she/it, phủ định dùng "doesn''t" (does not), không dùng "don''t".'),
  ('ex-a1-present-simple:q4', 'ex-a1-present-simple', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"In \"My father usually drinks tea\", the verb is correct.","answer":true}'::jsonb, '"My father" = he → động từ thêm -s: drinks. Trạng từ tần suất "usually" đứng trước động từ thường.'),
  ('ex-a1-present-simple:q5', 'ex-a1-present-simple', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi thức dậy lúc 6 giờ mỗi ngày.","acceptedAnswers":["I wake up at 6 every day.","I wake up at six every day.","I wake up at 6 o''clock every day.","I wake up at six o''clock every day.","I get up at 6 every day.","I get up at six every day.","I get up at six o''clock every day."]}'::jsonb, 'Thói quen hằng ngày dùng hiện tại đơn: I wake up / get up at six (o''clock) every day.'),
  ('ex-a1-articles:q1', 'ex-a1-articles', 0, 'multiple_choice', 'I eat ___ apple every morning.', null, '{}'::jsonb, '"Apple" bắt đầu bằng nguyên âm /æ/ nên dùng "an".'),
  ('ex-a1-articles:q2', 'ex-a1-articles', 1, 'multiple_choice', 'She is ___ university student.', null, '{}'::jsonb, '"University" phát âm /ˌjuː.../ bắt đầu bằng phụ âm /j/ nên dùng "a" dù chữ cái đầu là "u".'),
  ('ex-a1-articles:q3', 'ex-a1-articles', 2, 'fill_blank', 'Điền mạo từ.', null, '{"sentence":"I have a cat. ___ cat is black.","acceptedAnswers":["The"]}'::jsonb, 'Lần thứ hai nhắc đến "cat", người nghe đã biết là con mèo nào → dùng "the".'),
  ('ex-a1-articles:q4', 'ex-a1-articles', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"He is an honest man\" uses the correct article.","answer":true}'::jsonb, 'Chữ "h" trong "honest" là âm câm, từ bắt đầu bằng nguyên âm /ɒ/ → "an honest man".'),
  ('ex-a1-articles:q5', 'ex-a1-articles', 4, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"The sun rises in a east.","acceptedAnswers":["The sun rises in the east."]}'::jsonb, 'Phương hướng duy nhất (the east, the west...) dùng "the".'),
  ('ex-a1-reading-day:q1', 'ex-a1-reading-day', 0, 'true_false', 'Đúng hay sai theo đoạn văn?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{"statement":"Linh goes to work by bus.","answer":false}'::jsonb, 'Đoạn văn viết "She goes to work by motorbike" — cô ấy đi làm bằng xe máy.'),
  ('ex-a1-reading-day:q2', 'ex-a1-reading-day', 1, 'multiple_choice', 'What time does Linh wake up?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{}'::jsonb, '"Half past six" = 6 giờ 30 phút.'),
  ('ex-a1-reading-day:q3', 'ex-a1-reading-day', 2, 'multiple_choice', 'What does Linh do on Sundays?', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{}'::jsonb, 'Câu cuối: "On Sundays, she visits her parents."'),
  ('ex-a1-reading-day:q4', 'ex-a1-reading-day', 3, 'fill_blank', 'Hoàn thành câu theo đoạn văn (một từ).', 'Linh is 24 years old. She lives in Da Nang and works in an office. Every day, she wakes up at half past six and has bánh mì for breakfast. She goes to work by motorbike. In the evening, she studies English for thirty minutes. On Sundays, she visits her parents.', '{"sentence":"Linh lives in ___.","acceptedAnswers":["Da Nang","Danang"]}'::jsonb, '"She lives in Da Nang."'),
  ('ex-a2-past-simple:q1', 'ex-a2-past-simple', 0, 'multiple_choice', 'Yesterday I ___ my grandparents.', null, '{}'::jsonb, '"Yesterday" là mốc thời gian đã kết thúc → quá khứ đơn: visited.'),
  ('ex-a2-past-simple:q2', 'ex-a2-past-simple', 1, 'fill_blank', 'Điền dạng quá khứ của "go".', null, '{"sentence":"We ___ to Hoi An last month.","acceptedAnswers":["went"]}'::jsonb, '"Go" là động từ bất quy tắc: go → went → gone.'),
  ('ex-a2-past-simple:q3', 'ex-a2-past-simple', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Did you saw the film last night?","acceptedAnswers":["Did you see the film last night?"]}'::jsonb, 'Sau "did" động từ trở về nguyên mẫu: Did you see...?'),
  ('ex-a2-past-simple:q4', 'ex-a2-past-simple', 3, 'matching', 'Nối động từ với dạng quá khứ.', null, '{"pairs":[{"left":"buy","right":"bought"},{"left":"eat","right":"ate"},{"left":"write","right":"wrote"},{"left":"take","right":"took"}]}'::jsonb, 'Đây đều là động từ bất quy tắc thường gặp, cần học thuộc.'),
  ('ex-a2-past-simple:q5', 'ex-a2-past-simple', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi đã không đi làm hôm qua.","acceptedAnswers":["I didn''t go to work yesterday.","I did not go to work yesterday."]}'::jsonb, 'Phủ định quá khứ đơn: didn''t + động từ nguyên mẫu.'),
  ('ex-a2-future:q1', 'ex-a2-future', 0, 'multiple_choice', '"The phone is ringing." — "OK, I ___ answer it."', null, '{}'::jsonb, 'Quyết định đưa ra ngay lúc nói → dùng "will".'),
  ('ex-a2-future:q2', 'ex-a2-future', 1, 'multiple_choice', 'I bought a plane ticket. I ___ visit Japan in May.', null, '{}'::jsonb, 'Kế hoạch đã có từ trước (đã mua vé) → "be going to".'),
  ('ex-a2-future:q3', 'ex-a2-future', 2, 'true_false', 'Đúng hay sai?', null, '{"statement":"Look at those dark clouds! It is going to rain.","answer":true}'::jsonb, 'Dự đoán dựa trên dấu hiệu ở hiện tại (mây đen) → "be going to" là tự nhiên nhất.'),
  ('ex-a2-future:q4', 'ex-a2-future', 3, 'ordering', 'Sắp xếp thành câu đúng.', null, '{"tokens":["What","are","you","going","to","do","this weekend","?"]}'::jsonb, 'Câu hỏi: Từ để hỏi + am/is/are + chủ ngữ + going to + động từ?'),
  ('ex-b1-present-perfect:q1', 'ex-b1-present-perfect', 0, 'multiple_choice', 'I ___ to Singapore three times.', null, '{}'::jsonb, 'Nói về trải nghiệm (số lần) không nêu thời điểm → hiện tại hoàn thành.'),
  ('ex-b1-present-perfect:q2', 'ex-b1-present-perfect', 1, 'multiple_choice', 'I ___ to Singapore in 2023.', null, '{}'::jsonb, 'Có mốc thời gian cụ thể đã kết thúc (in 2023) → quá khứ đơn.'),
  ('ex-b1-present-perfect:q3', 'ex-b1-present-perfect', 2, 'fill_blank', 'Điền "for" hoặc "since".', null, '{"sentence":"She has worked here ___ 2020.","acceptedAnswers":["since"]}'::jsonb, '"Since" + mốc thời gian (2020); "for" + khoảng thời gian (five years).'),
  ('ex-b1-present-perfect:q4', 'ex-b1-present-perfect', 3, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I have finished the report yesterday.","acceptedAnswers":["I finished the report yesterday."]}'::jsonb, 'Không dùng hiện tại hoàn thành với "yesterday" → dùng quá khứ đơn.'),
  ('ex-b1-present-perfect:q5', 'ex-b1-present-perfect', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Bạn đã từng ăn sầu riêng chưa?","acceptedAnswers":["Have you ever eaten durian?","Have you ever tried durian?"]}'::jsonb, 'Hỏi về trải nghiệm: Have you ever + V3? — eat → ate → eaten.'),
  ('ex-b1-standup:q1', 'ex-b1-standup', 0, 'multiple_choice', 'Which sentence best describes what you did yesterday in a stand-up?', null, '{}'::jsonb, 'Việc đã làm hôm qua dùng quá khứ đơn: finished, opened. "PR" = pull request.'),
  ('ex-b1-standup:q2', 'ex-b1-standup', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"I''m ___ on the database migration. I need access to the staging server.","acceptedAnswers":["blocked","stuck"]}'::jsonb, '"I''m blocked on X" = tôi bị chặn/không thể tiếp tục việc X. "Stuck" cũng tự nhiên.'),
  ('ex-b1-standup:q3', 'ex-b1-standup', 2, 'matching', 'Nối cụm từ với nghĩa.', null, '{"pairs":[{"left":"on track","right":"đúng tiến độ"},{"left":"heads-up","right":"báo trước"},{"left":"pair with","right":"làm cặp cùng"},{"left":"follow up","right":"theo dõi tiếp"}]}'::jsonb, 'Đây là các cụm từ rất hay dùng trong họp nhóm phần mềm.'),
  ('ex-b1-standup:q4', 'ex-b1-standup', 3, 'ordering', 'Sắp xếp thành câu lịch sự để nhờ giúp đỡ.', null, '{"tokens":["Could","someone","help me","look into","this issue","?"]}'::jsonb, '"Could someone...?" là cách nhờ vả lịch sự; "look into" = điều tra, xem xét.'),
  ('ex-b1-standup:q5', 'ex-b1-standup', 4, 'true_false', 'Đúng hay sai?', null, '{"statement":"In a stand-up, \"Today I''m going to write unit tests for the login flow\" is a natural way to describe your plan.","answer":true}'::jsonb, 'Kế hoạch trong ngày thường dùng "I''m going to..." hoặc "I''ll...". Câu này tự nhiên và rõ ràng.'),
  ('ex-b1-code-review:q1', 'ex-b1-code-review', 0, 'multiple_choice', 'Which review comment is the most constructive?', null, '{}'::jsonb, 'Góp ý tốt đưa ra đề xuất cụ thể và lý do. Dạng câu hỏi "Could we...?" nhẹ nhàng hơn.'),
  ('ex-b1-code-review:q2', 'ex-b1-code-review', 1, 'matching', 'Nối viết tắt với nghĩa.', null, '{"pairs":[{"left":"LGTM","right":"Looks good to me"},{"left":"nit","right":"Minor, non-blocking suggestion"},{"left":"WIP","right":"Work in progress"}]}'::jsonb, 'Các viết tắt phổ biến trong pull request. "nit" (nitpick) là góp ý nhỏ, không bắt buộc sửa.'),
  ('ex-b1-code-review:q3', 'ex-b1-code-review', 2, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"Good catch! I ___ fixed it in the latest commit.","acceptedAnswers":["have","''ve"]}'::jsonb, 'Kết quả vừa hoàn thành, liên quan đến hiện tại → hiện tại hoàn thành: I have fixed it.'),
  ('ex-b1-code-review:q4', 'ex-b1-code-review', 3, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Cảm ơn bạn đã review.","acceptedAnswers":["Thanks for the review.","Thank you for the review.","Thanks for reviewing.","Thank you for reviewing."]}'::jsonb, 'Thanks/Thank you for + danh từ hoặc V-ing.'),
  ('ex-b2-conditionals:q1', 'ex-b2-conditionals', 0, 'multiple_choice', 'If I ___ more time, I would learn Japanese.', null, '{}'::jsonb, 'Loại 2 (không có thật ở hiện tại): If + quá khứ đơn, would + V.'),
  ('ex-b2-conditionals:q2', 'ex-b2-conditionals', 1, 'multiple_choice', 'If she had left earlier, she ___ the train.', null, '{}'::jsonb, 'Loại 3 (không có thật trong quá khứ): If + had V3, would have + V3.'),
  ('ex-b2-conditionals:q3', 'ex-b2-conditionals', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"If I would be you, I would accept the offer.","acceptedAnswers":["If I were you, I would accept the offer.","If I were you, I''d accept the offer."]}'::jsonb, 'Không dùng "would" trong mệnh đề "if". Lời khuyên cố định: "If I were you...".'),
  ('ex-b2-conditionals:q4', 'ex-b2-conditionals', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"If we had tested the code, we wouldn''t be fixing bugs now\" is a correct mixed conditional.","answer":true}'::jsonb, 'Điều kiện hỗn hợp: nguyên nhân trong quá khứ (had tested), kết quả ở hiện tại (wouldn''t be fixing).'),
  ('ex-c1-inversion:q1', 'ex-c1-inversion', 0, 'multiple_choice', 'Never ___ such a beautiful sunset.', null, '{}'::jsonb, 'Trạng từ phủ định đứng đầu câu → đảo trợ động từ lên trước chủ ngữ: Never have I seen...'),
  ('ex-c1-inversion:q2', 'ex-c1-inversion', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"No sooner had we sat down ___ the fire alarm went off.","acceptedAnswers":["than"]}'::jsonb, 'Cấu trúc cố định: No sooner had + S + V3 + than + quá khứ đơn.'),
  ('ex-c1-inversion:q3', 'ex-c1-inversion', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Not only she speaks French, but she also speaks Arabic.","acceptedAnswers":["Not only does she speak French, but she also speaks Arabic.","Not only does she speak French but she also speaks Arabic."]}'::jsonb, '"Not only" đứng đầu câu cần đảo ngữ với trợ động từ: Not only does she speak...'),
  ('ex-c2-cleft:q1', 'ex-c2-cleft', 0, 'multiple_choice', 'Which sentence emphasises that the problem was the deadline (not the budget)?', null, '{}'::jsonb, 'It-cleft: It + be + thành phần nhấn mạnh + that/who + phần còn lại.'),
  ('ex-c2-cleft:q2', 'ex-c2-cleft', 1, 'ordering', 'Sắp xếp thành câu chẻ dạng "What...".', null, '{"tokens":["What","I need","is","a clear explanation","."]}'::jsonb, 'Wh-cleft: What + mệnh đề + be + thông tin được nhấn mạnh.'),
  ('ex-c2-cleft:q3', 'ex-c2-cleft', 2, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"It was in 2019 when she moved to London\" is the standard form of an it-cleft.","answer":false}'::jsonb, 'Với it-cleft, dạng chuẩn dùng "that": It was in 2019 that she moved to London. "When" ít được chấp nhận trong văn viết trang trọng.'),
  ('ex-a1-personal-info:q1', 'ex-a1-personal-info', 0, 'multiple_choice', '"How old are you?" — Choose the correct answer.', null, '{}'::jsonb, 'Nói tuổi dùng "be": I''m 25 hoặc I''m 25 years old. Không dùng "have", và nếu có "years" thì phải có "old".'),
  ('ex-a1-personal-info:q2', 'ex-a1-personal-info', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"My phone number ___ 0912 345 678.","acceptedAnswers":["is"]}'::jsonb, '"My phone number" là danh từ số ít nên dùng "is".'),
  ('ex-a1-personal-info:q3', 'ex-a1-personal-info', 2, 'matching', 'Nối số với cách viết bằng chữ.', null, '{"pairs":[{"left":"13","right":"thirteen"},{"left":"30","right":"thirty"},{"left":"15","right":"fifteen"},{"left":"50","right":"fifty"}]}'::jsonb, 'Số -teen (13–19) nhấn âm cuối: thirTEEN. Số -ty (20, 30…) nhấn âm đầu: THIRty.'),
  ('ex-a1-personal-info:q4', 'ex-a1-personal-info', 3, 'ordering', 'Sắp xếp thành câu hỏi đúng.', null, '{"tokens":["Where","do","you","live","?"]}'::jsonb, 'Câu hỏi với động từ thường: Từ để hỏi + do/does + chủ ngữ + động từ?'),
  ('ex-a1-personal-info:q5', 'ex-a1-personal-info', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi 20 tuổi.","acceptedAnswers":["I''m 20.","I am 20.","I''m twenty.","I am twenty.","I''m 20 years old.","I am 20 years old.","I''m twenty years old.","I am twenty years old."]}'::jsonb, 'Tuổi: I am (I''m) + số (+ years old).'),
  ('ex-a1-personal-info:q6', 'ex-a1-personal-info', 5, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"When is your birthday?\" — \"It''s on the 5th of May.\" is a correct answer.","answer":true}'::jsonb, 'Ngày cụ thể dùng giới từ "on": on the 5th of May, on Monday.'),
  ('ex-a1-present-continuous:q1', 'ex-a1-present-continuous', 0, 'multiple_choice', 'Look! The baby ___.', null, '{}'::jsonb, '"Look!" cho biết việc đang diễn ra → is + V-ing. Không được bỏ "is".'),
  ('ex-a1-present-continuous:q2', 'ex-a1-present-continuous', 1, 'fill_blank', 'Điền am / is / are.', null, '{"sentence":"They ___ watching TV right now.","acceptedAnswers":["are"]}'::jsonb, '"They" đi với "are".'),
  ('ex-a1-present-continuous:q3', 'ex-a1-present-continuous', 2, 'fill_blank', 'Điền dạng V-ing của "swim".', null, '{"sentence":"He is ___ in the pool.","acceptedAnswers":["swimming"]}'::jsonb, 'Động từ một âm tiết kết thúc bằng phụ âm–nguyên âm–phụ âm thì gấp đôi phụ âm cuối: swim → swimming.'),
  ('ex-a1-present-continuous:q4', 'ex-a1-present-continuous', 3, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I am knowing the answer.","acceptedAnswers":["I know the answer."]}'::jsonb, '"Know" là động từ chỉ trạng thái, không dùng ở dạng tiếp diễn.'),
  ('ex-a1-present-continuous:q5', 'ex-a1-present-continuous', 4, 'multiple_choice', 'She ___ to work every day, but today she is working from home.', null, '{}'::jsonb, '"Every day" là thói quen → hiện tại đơn: goes.'),
  ('ex-a1-present-continuous:q6', 'ex-a1-present-continuous', 5, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Bạn đang làm gì vậy?","acceptedAnswers":["What are you doing?","What are you doing now?","What are you doing right now?"]}'::jsonb, 'Câu hỏi hiện tại tiếp diễn: What + are + you + V-ing?'),
  ('ex-a1-plurals:q1', 'ex-a1-plurals', 0, 'matching', 'Nối danh từ số ít với dạng số nhiều.', null, '{"pairs":[{"left":"child","right":"children"},{"left":"man","right":"men"},{"left":"person","right":"people"},{"left":"tooth","right":"teeth"}]}'::jsonb, 'Đây là các danh từ số nhiều bất quy tắc thường gặp nhất.'),
  ('ex-a1-plurals:q2', 'ex-a1-plurals', 1, 'multiple_choice', 'There are three ___ in my team.', null, '{}'::jsonb, 'woman → women (số nhiều bất quy tắc).'),
  ('ex-a1-plurals:q3', 'ex-a1-plurals', 2, 'fill_blank', 'Điền dạng số nhiều của "box".', null, '{"sentence":"I have two ___ of books.","acceptedAnswers":["boxes"]}'::jsonb, 'Danh từ tận cùng bằng -x thêm -es: box → boxes.'),
  ('ex-a1-plurals:q4', 'ex-a1-plurals', 3, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"These book is very interesting.","acceptedAnswers":["This book is very interesting.","These books are very interesting."]}'::jsonb, '"These" đi với danh từ số nhiều và "are"; "this" đi với số ít và "is".'),
  ('ex-a1-plurals:q5', 'ex-a1-plurals', 4, 'multiple_choice', 'Look at ___ birds up in the sky!', null, '{}'::jsonb, 'Ở xa + số nhiều → those.'),
  ('ex-a1-possessives:q1', 'ex-a1-possessives', 0, 'multiple_choice', 'This is my sister. ___ name is Hoa.', null, '{}'::jsonb, 'Sister → she → tính từ sở hữu "her".'),
  ('ex-a1-possessives:q2', 'ex-a1-possessives', 1, 'fill_blank', 'Điền dạng sở hữu của "Nam".', null, '{"sentence":"That is ___ motorbike.","acceptedAnswers":["Nam''s"]}'::jsonb, 'Sở hữu cách: tên người + ''s.'),
  ('ex-a1-possessives:q3', 'ex-a1-possessives', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"The dog is eating it''s food.","acceptedAnswers":["The dog is eating its food."]}'::jsonb, '"its" = của nó; "it''s" = it is.'),
  ('ex-a1-possessives:q4', 'ex-a1-possessives', 3, 'multiple_choice', '___ bag is this? — It''s mine.', null, '{}'::jsonb, '"Whose" hỏi về chủ sở hữu (của ai). "Who''s" = who is.'),
  ('ex-a1-possessives:q5', 'ex-a1-possessives', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Đây là ô tô của bố tôi.","acceptedAnswers":["This is my father''s car.","This is my dad''s car."]}'::jsonb, 'Người sở hữu đứng trước: my father''s car (ngược thứ tự với tiếng Việt).'),
  ('ex-a1-there-is:q1', 'ex-a1-there-is', 0, 'multiple_choice', '___ a supermarket near my house.', null, '{}'::jsonb, '"a supermarket" là số ít → there is.'),
  ('ex-a1-there-is:q2', 'ex-a1-there-is', 1, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Have many people in the park.","acceptedAnswers":["There are many people in the park.","There are a lot of people in the park.","There are lots of people in the park."]}'::jsonb, '"Có" chỉ sự tồn tại dịch là "there is/are", không dùng "have". "People" là số nhiều → there are.'),
  ('ex-a1-there-is:q3', 'ex-a1-there-is', 2, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"___ there any eggs in the fridge?","acceptedAnswers":["Are"]}'::jsonb, 'Câu hỏi với danh từ số nhiều: Are there any…?'),
  ('ex-a1-there-is:q4', 'ex-a1-there-is', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"There is two banks on this street.\" is correct.","answer":false}'::jsonb, '"Two banks" là số nhiều → There are two banks…'),
  ('ex-a1-there-is:q5', 'ex-a1-there-is', 4, 'ordering', 'Sắp xếp thành câu đúng.', null, '{"tokens":["There","aren''t","any","chairs","in","the","room","."]}'::jsonb, 'Phủ định số nhiều: There aren''t any + danh từ số nhiều.'),
  ('ex-a1-prepositions-place:q1', 'ex-a1-prepositions-place', 0, 'multiple_choice', 'The cat is sleeping ___ the bed. (ở dưới gầm giường)', null, '{}'::jsonb, 'Ở dưới → under.'),
  ('ex-a1-prepositions-place:q2', 'ex-a1-prepositions-place', 1, 'multiple_choice', 'The pharmacy is ___ the bank and the supermarket.', null, '{}'::jsonb, 'Ở giữa hai địa điểm: between A and B. "Next" phải đi với "to": next to.'),
  ('ex-a1-prepositions-place:q3', 'ex-a1-prepositions-place', 2, 'fill_blank', 'Điền giới từ (ở trong).', null, '{"sentence":"My keys are ___ my bag.","acceptedAnswers":["in"]}'::jsonb, 'Bên trong một vật chứa → in.'),
  ('ex-a1-prepositions-place:q4', 'ex-a1-prepositions-place', 3, 'matching', 'Nối giới từ với nghĩa.', null, '{"pairs":[{"left":"in front of","right":"phía trước"},{"left":"behind","right":"phía sau"},{"left":"next to","right":"bên cạnh"},{"left":"opposite","right":"đối diện"}]}'::jsonb, 'Đây là các giới từ chỉ vị trí hay dùng khi chỉ đường.'),
  ('ex-a1-prepositions-place:q5', 'ex-a1-prepositions-place', 4, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"The phone is in the table.","acceptedAnswers":["The phone is on the table."]}'::jsonb, 'Đặt trên bề mặt → on.'),
  ('ex-a1-can:q1', 'ex-a1-can', 0, 'multiple_choice', 'My brother ___ speak Japanese.', null, '{}'::jsonb, '"Can" không thêm -s và không có "to" theo sau.'),
  ('ex-a1-can:q2', 'ex-a1-can', 1, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I can to swim very well.","acceptedAnswers":["I can swim very well."]}'::jsonb, 'can + V nguyên mẫu (không "to").'),
  ('ex-a1-can:q3', 'ex-a1-can', 2, 'fill_blank', 'Điền từ để nhờ vả lịch sự.', null, '{"sentence":"___ you help me, please?","acceptedAnswers":["Can","Could"]}'::jsonb, 'Can/Could you…? dùng để nhờ ai đó. "Could" lịch sự hơn.'),
  ('ex-a1-can:q4', 'ex-a1-can', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"She can drives a car.\" is correct.","answer":false}'::jsonb, 'Sau "can" là động từ nguyên mẫu: She can drive a car.'),
  ('ex-a1-can:q5', 'ex-a1-can', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Tôi không biết nấu ăn.","acceptedAnswers":["I can''t cook.","I cannot cook.","I don''t know how to cook."]}'::jsonb, '"Biết làm gì" (khả năng) thường dịch là "can": I can''t cook.'),
  ('ex-a1-countable:q1', 'ex-a1-countable', 0, 'multiple_choice', 'Can I have ___ water, please?', null, '{}'::jsonb, '"Water" không đếm được → không dùng "a" hay "many". Lời đề nghị, yêu cầu dùng "some".'),
  ('ex-a1-countable:q2', 'ex-a1-countable', 1, 'multiple_choice', 'There isn''t ___ milk in the fridge.', null, '{}'::jsonb, 'Câu phủ định dùng "any".'),
  ('ex-a1-countable:q3', 'ex-a1-countable', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I eat a rice every day.","acceptedAnswers":["I eat rice every day."]}'::jsonb, '"Rice" không đếm được, không dùng "a".'),
  ('ex-a1-countable:q4', 'ex-a1-countable', 3, 'matching', 'Nối từ với cách dùng.', null, '{"pairs":[{"left":"some","right":"một ít (câu khẳng định)"},{"left":"any","right":"nào (câu phủ định, câu hỏi)"},{"left":"many","right":"nhiều (danh từ đếm được)"},{"left":"much","right":"nhiều (danh từ không đếm được)"}]}'::jsonb, 'many eggs, much rice; some trong câu khẳng định, any trong câu phủ định và câu hỏi.'),
  ('ex-a1-countable:q5', 'ex-a1-countable', 4, 'fill_blank', 'Điền much hoặc many.', null, '{"sentence":"How ___ eggs do you need?","acceptedAnswers":["many"]}'::jsonb, '"Eggs" đếm được số nhiều → how many.'),
  ('ex-a1-ordering-food:q1', 'ex-a1-ordering-food', 0, 'multiple_choice', 'Which is the most polite way to order?', null, '{}'::jsonb, '"I''d like…, please." là cách gọi món lịch sự và tự nhiên.'),
  ('ex-a1-ordering-food:q2', 'ex-a1-ordering-food', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"Could I have the ___, please? We would like to pay.","acceptedAnswers":["bill","check"]}'::jsonb, '"The bill" (Anh) hoặc "the check" (Mỹ) là hoá đơn.'),
  ('ex-a1-ordering-food:q3', 'ex-a1-ordering-food', 2, 'ordering', 'Sắp xếp thành câu hỏi lịch sự.', null, '{"tokens":["Can","I","see","the","menu",",","please","?"]}'::jsonb, 'Can I + V…, please? là cách xin lịch sự.'),
  ('ex-a1-ordering-food:q4', 'ex-a1-ordering-food', 3, 'matching', 'Nối câu hỏi của nhân viên với câu trả lời phù hợp.', null, '{"pairs":[{"left":"Are you ready to order?","right":"Yes, I''d like the chicken, please."},{"left":"Anything else?","right":"No, that''s all, thanks."},{"left":"For here or to go?","right":"To go, please."}]}'::jsonb, 'Ba câu hỏi rất hay gặp khi gọi món ở quán.'),
  ('ex-a1-ordering-food:q5', 'ex-a1-ordering-food', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Cho tôi một ly trà đá.","acceptedAnswers":["I''d like an iced tea.","I would like an iced tea.","I''d like an iced tea, please.","I would like an iced tea, please.","Can I have an iced tea?","Can I have an iced tea, please?","I''d like a glass of iced tea, please."]}'::jsonb, 'Gọi món: I''d like… / Can I have…? "Trà đá" = iced tea.'),
  ('ex-a1-shopping:q1', 'ex-a1-shopping', 0, 'multiple_choice', 'How ___ is this T-shirt?', null, '{}'::jsonb, 'Hỏi giá: How much is/are…?'),
  ('ex-a1-shopping:q2', 'ex-a1-shopping', 1, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"How many money do you have?","acceptedAnswers":["How much money do you have?"]}'::jsonb, '"Money" không đếm được → how much.'),
  ('ex-a1-shopping:q3', 'ex-a1-shopping', 2, 'multiple_choice', 'This bag is 2,000,000 dong. It''s too ___ for me.', null, '{}'::jsonb, '"Too expensive" = đắt quá.'),
  ('ex-a1-shopping:q4', 'ex-a1-shopping', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"How much are these shoes?\" — \"They''re 500,000 dong.\" is correct.","answer":true}'::jsonb, '"Shoes" số nhiều → How much are…? — They''re…'),
  ('ex-a1-shopping:q5', 'ex-a1-shopping', 4, 'fill_blank', 'Điền giới từ.', null, '{"sentence":"Can I pay ___ card?","acceptedAnswers":["by"]}'::jsonb, 'pay by card, nhưng pay in cash.'),
  ('ex-a2-past-continuous:q1', 'ex-a2-past-continuous', 0, 'multiple_choice', 'I ___ dinner when the phone rang.', null, '{}'::jsonb, 'Hành động đang diễn ra (nấu ăn) bị một hành động ngắn (điện thoại reo) cắt ngang → quá khứ tiếp diễn.'),
  ('ex-a2-past-continuous:q2', 'ex-a2-past-continuous', 1, 'fill_blank', 'Điền was hoặc were.', null, '{"sentence":"What ___ you doing at 9 o''clock last night?","acceptedAnswers":["were"]}'::jsonb, '"You" đi với "were".'),
  ('ex-a2-past-continuous:q3', 'ex-a2-past-continuous', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"While I walked home, it started to rain.","acceptedAnswers":["While I was walking home, it started to rain."]}'::jsonb, 'Sau "while" là hành động kéo dài → quá khứ tiếp diễn.'),
  ('ex-a2-past-continuous:q4', 'ex-a2-past-continuous', 3, 'multiple_choice', 'At 7 a.m. yesterday, I ___.', null, '{}'::jsonb, 'Việc đang diễn ra tại một thời điểm cụ thể trong quá khứ → quá khứ tiếp diễn.'),
  ('ex-a2-past-continuous:q5', 'ex-a2-past-continuous', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Lúc đó tôi đang xem TV.","acceptedAnswers":["I was watching TV at that time.","I was watching TV then.","At that time I was watching TV.","At that time, I was watching TV."]}'::jsonb, '"Lúc đó… đang…" → was/were + V-ing.'),
  ('ex-a2-used-to:q1', 'ex-a2-used-to', 0, 'multiple_choice', 'I ___ live in Hue, but now I live in Hanoi.', null, '{}'::jsonb, 'Trạng thái trong quá khứ nay không còn → used to + V.'),
  ('ex-a2-used-to:q2', 'ex-a2-used-to', 1, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"She didn''t ___ to like vegetables.","acceptedAnswers":["use"]}'::jsonb, 'Sau "didn''t" dùng "use to", không phải "used to".'),
  ('ex-a2-used-to:q3', 'ex-a2-used-to', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"Did you used to play football?","acceptedAnswers":["Did you use to play football?"]}'::jsonb, 'Câu hỏi với "did": Did + S + use to + V?'),
  ('ex-a2-used-to:q4', 'ex-a2-used-to', 3, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"My grandfather used to be a teacher.\" means he is still a teacher now.","answer":false}'::jsonb, '"Used to" chỉ điều đúng trong quá khứ nhưng nay không còn nữa.'),
  ('ex-a2-used-to:q5', 'ex-a2-used-to', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Hồi nhỏ tôi thường đi bơi ở sông.","acceptedAnswers":["I used to swim in the river when I was a child.","When I was a child, I used to swim in the river.","I used to go swimming in the river when I was a child.","When I was a child, I used to go swimming in the river.","I used to swim in the river when I was young.","When I was young, I used to swim in the river."]}'::jsonb, 'Thói quen trong quá khứ: used to + V. "Hồi nhỏ" = when I was a child / when I was young.'),
  ('ex-a2-reading-trip:q1', 'ex-a2-reading-trip', 0, 'multiple_choice', 'How did they travel to Sa Pa?', 'Last summer, Huy and his friends went to Sa Pa by night train. The journey took about eight hours. When they arrived, it was raining, so they stayed in their hotel and played cards. The next morning the weather was beautiful. They walked to a small village and had lunch with a local family. While they were walking back, Huy dropped his phone in a stream! Luckily, it still worked. Huy says it was the best trip of his life.', '{}'::jsonb, 'Câu đầu: "went to Sa Pa by night train".'),
  ('ex-a2-reading-trip:q2', 'ex-a2-reading-trip', 1, 'true_false', 'Đúng hay sai theo câu chuyện?', 'Last summer, Huy and his friends went to Sa Pa by night train. The journey took about eight hours. When they arrived, it was raining, so they stayed in their hotel and played cards. The next morning the weather was beautiful. They walked to a small village and had lunch with a local family. While they were walking back, Huy dropped his phone in a stream! Luckily, it still worked. Huy says it was the best trip of his life.', '{"statement":"When they arrived, the weather was sunny.","answer":false}'::jsonb, '"When they arrived, it was raining" — trời đang mưa.'),
  ('ex-a2-reading-trip:q3', 'ex-a2-reading-trip', 2, 'multiple_choice', 'What happened while they were walking back?', 'Last summer, Huy and his friends went to Sa Pa by night train. The journey took about eight hours. When they arrived, it was raining, so they stayed in their hotel and played cards. The next morning the weather was beautiful. They walked to a small village and had lunch with a local family. While they were walking back, Huy dropped his phone in a stream! Luckily, it still worked. Huy says it was the best trip of his life.', '{}'::jsonb, '"While they were walking back, Huy dropped his phone in a stream!"'),
  ('ex-a2-reading-trip:q4', 'ex-a2-reading-trip', 3, 'fill_blank', 'Hoàn thành câu theo câu chuyện.', 'Last summer, Huy and his friends went to Sa Pa by night train. The journey took about eight hours. When they arrived, it was raining, so they stayed in their hotel and played cards. The next morning the weather was beautiful. They walked to a small village and had lunch with a local family. While they were walking back, Huy dropped his phone in a stream! Luckily, it still worked. Huy says it was the best trip of his life.', '{"sentence":"The journey took about ___ hours.","acceptedAnswers":["eight","8"]}'::jsonb, '"The journey took about eight hours."'),
  ('ex-a2-reading-trip:q5', 'ex-a2-reading-trip', 4, 'true_false', 'Đúng hay sai theo câu chuyện?', 'Last summer, Huy and his friends went to Sa Pa by night train. The journey took about eight hours. When they arrived, it was raining, so they stayed in their hotel and played cards. The next morning the weather was beautiful. They walked to a small village and had lunch with a local family. While they were walking back, Huy dropped his phone in a stream! Luckily, it still worked. Huy says it was the best trip of his life.', '{"statement":"Huy''s phone stopped working after he dropped it.","answer":false}'::jsonb, '"Luckily, it still worked." — điện thoại vẫn hoạt động.'),
  ('ex-a2-future-arrangements:q1', 'ex-a2-future-arrangements', 0, 'multiple_choice', 'I ___ my dentist at 10 tomorrow. I booked it last week.', null, '{}'::jsonb, 'Lịch hẹn đã sắp xếp → hiện tại tiếp diễn.'),
  ('ex-a2-future-arrangements:q2', 'ex-a2-future-arrangements', 1, 'multiple_choice', 'The train to Hai Phong ___ at 6:15 tomorrow morning.', null, '{}'::jsonb, 'Lịch trình cố định → hiện tại đơn; "the train" số ít → leaves.'),
  ('ex-a2-future-arrangements:q3', 'ex-a2-future-arrangements', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"I meet my friends tonight at 7.","acceptedAnswers":["I''m meeting my friends tonight at 7.","I am meeting my friends tonight at 7.","I''m going to meet my friends tonight at 7.","I am going to meet my friends tonight at 7."]}'::jsonb, 'Kế hoạch cá nhân đã hẹn → hiện tại tiếp diễn (hoặc "going to").'),
  ('ex-a2-future-arrangements:q4', 'ex-a2-future-arrangements', 3, 'fill_blank', 'Điền từ còn thiếu.', null, '{"sentence":"What ___ you doing this weekend?","acceptedAnswers":["are"]}'::jsonb, 'Hỏi về kế hoạch: What are you doing + thời gian tương lai?'),
  ('ex-a2-future-arrangements:q5', 'ex-a2-future-arrangements', 4, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"The film starts at 8 p.m.\" uses the present simple because it is a fixed timetable.","answer":true}'::jsonb, 'Giờ chiếu phim theo thời gian biểu → hiện tại đơn.'),
  ('ex-a2-invitations:q1', 'ex-a2-invitations', 0, 'multiple_choice', 'How about ___ to the cinema tonight?', null, '{}'::jsonb, '"How about" + V-ing.'),
  ('ex-a2-invitations:q2', 'ex-a2-invitations', 1, 'multiple_choice', 'Which is the most polite way to say no to an invitation?', null, '{}'::jsonb, 'Từ chối lịch sự: thể hiện thiện chí ("I''d love to") và đưa lý do.'),
  ('ex-a2-invitations:q3', 'ex-a2-invitations', 2, 'fill_blank', 'Điền hai từ còn thiếu.', null, '{"sentence":"Would you like ___ dinner with us?","acceptedAnswers":["to have","to eat"]}'::jsonb, '"Would you like" + to V.'),
  ('ex-a2-invitations:q4', 'ex-a2-invitations', 3, 'ordering', 'Sắp xếp thành câu gợi ý.', null, '{"tokens":["Why","don''t","we","go","to","the","beach","?"]}'::jsonb, '"Why don''t we" + V nguyên mẫu?'),
  ('ex-a2-invitations:q5', 'ex-a2-invitations', 4, 'matching', 'Nối cấu trúc với dạng động từ theo sau.', null, '{"pairs":[{"left":"Let''s …","right":"+ V nguyên mẫu"},{"left":"How about …?","right":"+ V-ing"},{"left":"Would you like …?","right":"+ to V"}]}'::jsonb, 'Let''s go · How about going · Would you like to go.'),
  ('ex-a2-comparatives:q1', 'ex-a2-comparatives', 0, 'multiple_choice', 'Ho Chi Minh City is ___ than Da Lat.', null, '{}'::jsonb, 'Tính từ ngắn: hot → hotter (gấp đôi phụ âm cuối).'),
  ('ex-a2-comparatives:q2', 'ex-a2-comparatives', 1, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"My new phone is more cheaper than my old one.","acceptedAnswers":["My new phone is cheaper than my old one."]}'::jsonb, 'Không dùng "more" cùng "-er".'),
  ('ex-a2-comparatives:q3', 'ex-a2-comparatives', 2, 'fill_blank', 'Điền dạng so sánh hơn của "good".', null, '{"sentence":"Today is ___ than yesterday.","acceptedAnswers":["better"]}'::jsonb, 'good → better (bất quy tắc).'),
  ('ex-a2-comparatives:q4', 'ex-a2-comparatives', 3, 'multiple_choice', 'This flat is ___ comfortable than the old one.', null, '{}'::jsonb, 'Tính từ dài: more + adj + than.'),
  ('ex-a2-comparatives:q5', 'ex-a2-comparatives', 4, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"Lan is as tall as her brother\" means they are the same height.","answer":true}'::jsonb, 'as + adj + as = bằng nhau.'),
  ('ex-a2-superlatives:q1', 'ex-a2-superlatives', 0, 'multiple_choice', 'Fansipan is ___ mountain in Vietnam.', null, '{}'::jsonb, 'So sánh nhất: the + adj-est, luôn có "the".'),
  ('ex-a2-superlatives:q2', 'ex-a2-superlatives', 1, 'fill_blank', 'Điền dạng so sánh nhất của "good".', null, '{"sentence":"This is the ___ restaurant in our street.","acceptedAnswers":["best"]}'::jsonb, 'good → better → the best.'),
  ('ex-a2-superlatives:q3', 'ex-a2-superlatives', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"She is the most fast runner in the team.","acceptedAnswers":["She is the fastest runner in the team.","She is the fastest runner on the team."]}'::jsonb, 'Tính từ ngắn dùng "-est": the fastest.'),
  ('ex-a2-superlatives:q4', 'ex-a2-superlatives', 3, 'multiple_choice', 'Which is ___ expensive city in the world?', null, '{}'::jsonb, 'Tính từ dài: the most + adj.'),
  ('ex-a2-superlatives:q5', 'ex-a2-superlatives', 4, 'matching', 'Nối tính từ với dạng so sánh nhất.', null, '{"pairs":[{"left":"big","right":"the biggest"},{"left":"happy","right":"the happiest"},{"left":"bad","right":"the worst"},{"left":"beautiful","right":"the most beautiful"}]}'::jsonb, 'big → biggest (gấp đôi phụ âm), happy → happiest (y → i), bad → worst (bất quy tắc), beautiful → most beautiful (tính từ dài).'),
  ('ex-a2-obligation:q1', 'ex-a2-obligation', 0, 'multiple_choice', 'You ___ smoke in the hospital. It isn''t allowed.', null, '{}'::jsonb, 'Bị cấm → mustn''t.'),
  ('ex-a2-obligation:q2', 'ex-a2-obligation', 1, 'multiple_choice', 'It''s Sunday tomorrow, so I ___ get up early.', null, '{}'::jsonb, 'Không cần thiết → don''t have to.'),
  ('ex-a2-obligation:q3', 'ex-a2-obligation', 2, 'error_correction', 'Sửa lỗi sai.', null, '{"sentence":"You should to see a doctor.","acceptedAnswers":["You should see a doctor."]}'::jsonb, 'should + V nguyên mẫu (không "to").'),
  ('ex-a2-obligation:q4', 'ex-a2-obligation', 3, 'fill_blank', 'Điền dạng đúng của "have".', null, '{"sentence":"She ___ to wear a uniform at work. It''s a company rule.","acceptedAnswers":["has"]}'::jsonb, 'She → has to.'),
  ('ex-a2-obligation:q5', 'ex-a2-obligation', 4, 'translation', 'Dịch sang tiếng Anh.', null, '{"sourceVi":"Bạn nên uống nhiều nước hơn.","acceptedAnswers":["You should drink more water."]}'::jsonb, 'Lời khuyên: should + V.'),
  ('ex-a2-obligation:q6', 'ex-a2-obligation', 5, 'true_false', 'Đúng hay sai?', null, '{"statement":"\"I must finish this report today\" and \"I have to finish this report today\" both express obligation.","answer":true}'::jsonb, 'Cả hai đều diễn tả sự bắt buộc ("phải").')
