insert into public.assessments (id, title, title_vi, description, estimated_minutes) values
  ('placement-v1', 'Placement test', 'Bài kiểm tra xếp lớp', 'Ước lượng trình độ CEFR của bạn qua từ vựng, ngữ pháp, đọc, nghe và viết câu.', 12)
insert into public.assessment_questions (id, assessment_id, position, skill, level_id, type, prompt, payload, explanation_vi) values
  ('placement-v1:a1-1', 'placement-v1', 0, 'vocabulary', 'A1', 'multiple_choice', 'I''m ___. Can I have a sandwich?', '{"options":[{"id":"a","text":"hungry"},{"id":"b","text":"tired"},{"id":"c","text":"cold"}],"correctOptionId":"a"}'::jsonb, '"Hungry" (đói) phù hợp với việc muốn ăn bánh sandwich.'),
  ('placement-v1:a1-2', 'placement-v1', 1, 'grammar', 'A1', 'multiple_choice', 'She ___ from Vietnam.', '{"options":[{"id":"a","text":"am"},{"id":"b","text":"is"},{"id":"c","text":"are"}],"correctOptionId":"b"}'::jsonb, '"She" đi với "is".'),
  ('placement-v1:a1-3', 'placement-v1', 2, 'listening', 'A1', 'multiple_choice', 'What is Tom''s job?', '{"audioText":"Hi, I''m Tom. I''m a teacher, and I live in London.","options":[{"id":"a","text":"A doctor"},{"id":"b","text":"A teacher"},{"id":"c","text":"A student"}],"correctOptionId":"b"}'::jsonb, '"I''m a teacher" — Tom là giáo viên.'),
  ('placement-v1:a1-4', 'placement-v1', 3, 'writing', 'A1', 'ordering', 'Sắp xếp thành câu hỏi đúng.', '{"tokens":["Where","do","you","work","?"]}'::jsonb, 'Từ để hỏi + do + chủ ngữ + động từ?'),
  ('placement-v1:a2-1', 'placement-v1', 4, 'grammar', 'A2', 'multiple_choice', 'Yesterday we ___ to the beach.', '{"options":[{"id":"a","text":"go"},{"id":"b","text":"went"},{"id":"c","text":"have gone"}],"correctOptionId":"b"}'::jsonb, '"Yesterday" → quá khứ đơn: went.'),
  ('placement-v1:a2-2', 'placement-v1', 5, 'vocabulary', 'A2', 'multiple_choice', 'I need to book a ___ to Da Nang. I''m flying on Friday.', '{"options":[{"id":"a","text":"flight"},{"id":"b","text":"journey"},{"id":"c","text":"passport"}],"correctOptionId":"a"}'::jsonb, '"Flying" → đặt chuyến bay: book a flight.'),
  ('placement-v1:a2-3', 'placement-v1', 6, 'reading', 'A2', 'true_false', 'Đúng hay sai theo thông báo?', '{"statement":"A nine-year-old child can swim alone.","answer":false,"context":"SWIMMING POOL — Open 6 a.m. to 8 p.m. every day except Monday. Children under 10 must swim with an adult."}'::jsonb, 'Trẻ dưới 10 tuổi phải bơi cùng người lớn.'),
  ('placement-v1:a2-4', 'placement-v1', 7, 'listening', 'A2', 'multiple_choice', 'When does the speaker want to meet?', '{"audioText":"I''m sorry, I can''t come to the meeting on Thursday. Can we meet on Friday morning instead?","options":[{"id":"a","text":"Thursday morning"},{"id":"b","text":"Friday morning"},{"id":"c","text":"Friday afternoon"}],"correctOptionId":"b"}'::jsonb, '"Can we meet on Friday morning instead?"'),
  ('placement-v1:b1-1', 'placement-v1', 8, 'grammar', 'B1', 'multiple_choice', 'I ___ here since 2020.', '{"options":[{"id":"a","text":"work"},{"id":"b","text":"worked"},{"id":"c","text":"have worked"}],"correctOptionId":"c"}'::jsonb, '"Since 2020" (đến nay) → hiện tại hoàn thành.'),
  ('placement-v1:b1-2', 'placement-v1', 9, 'vocabulary', 'B1', 'multiple_choice', 'We need to finish the report before the ___ on Friday.', '{"options":[{"id":"a","text":"deadline"},{"id":"b","text":"delay"},{"id":"c","text":"appointment"}],"correctOptionId":"a"}'::jsonb, '"Deadline" là hạn chót phải hoàn thành.'),
  ('placement-v1:b1-3', 'placement-v1', 10, 'reading', 'B1', 'multiple_choice', 'What does Sarah say?', '{"context":"Hi Minh, thank you for your application. Unfortunately, the position has already been filled. However, we were impressed by your experience and would like to keep your CV for future openings. Best regards, Sarah","options":[{"id":"a","text":"Minh got the job."},{"id":"b","text":"The job is no longer available, but they may contact Minh later."},{"id":"c","text":"Minh needs more experience to apply."}],"correctOptionId":"b"}'::jsonb, '"The position has already been filled" (đã tuyển được người) nhưng họ giữ CV cho các vị trí sau.'),
  ('placement-v1:b1-4', 'placement-v1', 11, 'writing', 'B1', 'error_correction', 'Sửa lỗi sai trong câu.', '{"sentence":"If it will rain tomorrow, we will stay at home.","acceptedAnswers":["If it rains tomorrow, we will stay at home.","If it rains tomorrow, we''ll stay at home."]}'::jsonb, 'Câu điều kiện loại 1: mệnh đề "if" dùng hiện tại đơn, không dùng "will".'),
  ('placement-v1:b2-1', 'placement-v1', 12, 'grammar', 'B2', 'multiple_choice', 'If I ___ about the traffic, I would have left earlier.', '{"options":[{"id":"a","text":"knew"},{"id":"b","text":"had known"},{"id":"c","text":"would know"}],"correctOptionId":"b"}'::jsonb, 'Câu điều kiện loại 3: If + had V3, would have V3.'),
  ('placement-v1:b2-2', 'placement-v1', 13, 'vocabulary', 'B2', 'multiple_choice', 'The new system is faster, but there is a ___: it uses much more memory.', '{"options":[{"id":"a","text":"trade-off"},{"id":"b","text":"blocker"},{"id":"c","text":"nuance"}],"correctOptionId":"a"}'::jsonb, '"Trade-off" là sự đánh đổi: được tốc độ nhưng mất bộ nhớ.'),
  ('placement-v1:b2-3', 'placement-v1', 14, 'listening', 'B2', 'multiple_choice', 'What does the speaker suggest?', '{"audioText":"Although the results look promising, we shouldn''t draw any conclusions until we''ve tested the feature with real users.","options":[{"id":"a","text":"Launching the feature now"},{"id":"b","text":"Testing with real users before deciding"},{"id":"c","text":"Abandoning the feature"}],"correctOptionId":"b"}'::jsonb, '"We shouldn''t draw any conclusions until we''ve tested…" — chưa kết luận khi chưa thử với người dùng thật.'),
  ('placement-v1:b2-4', 'placement-v1', 15, 'writing', 'B2', 'translation', 'Dịch sang tiếng Anh.', '{"sourceVi":"Tôi ước mình đã học tiếng Anh sớm hơn.","acceptedAnswers":["I wish I had learned English earlier.","I wish I had learnt English earlier.","I wish I''d learned English earlier.","I wish I''d learnt English earlier.","I wish I had studied English earlier.","I wish I''d studied English earlier."]}'::jsonb, 'Ước điều trái với quá khứ: I wish + quá khứ hoàn thành (had + V3).'),
  ('placement-v1:c1-1', 'placement-v1', 16, 'grammar', 'C1', 'multiple_choice', 'Not only ___ late, but he also forgot the documents.', '{"options":[{"id":"a","text":"he was"},{"id":"b","text":"was he"},{"id":"c","text":"he is"}],"correctOptionId":"b"}'::jsonb, '"Not only" đứng đầu câu → đảo ngữ: was he.'),
  ('placement-v1:c1-2', 'placement-v1', 17, 'vocabulary', 'C1', 'multiple_choice', 'We added a cache to ___ the impact of the slow database.', '{"options":[{"id":"a","text":"mitigate"},{"id":"b","text":"aggravate"},{"id":"c","text":"negotiate"}],"correctOptionId":"a"}'::jsonb, '"Mitigate" = giảm thiểu tác động xấu.'),
  ('placement-v1:c1-3', 'placement-v1', 18, 'reading', 'C1', 'multiple_choice', 'What do the critics argue?', '{"context":"Remote work was once viewed as a perk reserved for a privileged few. Today, many companies treat it as the default, arguing that it widens the talent pool. Critics counter that spontaneous collaboration suffers when teams rarely meet in person.","options":[{"id":"a","text":"Remote work is too expensive for companies."},{"id":"b","text":"Unplanned teamwork happens less when people rarely meet."},{"id":"c","text":"Remote work makes it harder to find talented staff."}],"correctOptionId":"b"}'::jsonb, '"Spontaneous collaboration suffers" — sự cộng tác tự phát bị ảnh hưởng.'),
  ('placement-v1:c1-4', 'placement-v1', 19, 'writing', 'C1', 'error_correction', 'Sửa lỗi sai trong câu.', '{"sentence":"Hardly I had arrived when the meeting started.","acceptedAnswers":["Hardly had I arrived when the meeting started."]}'::jsonb, '"Hardly" đứng đầu câu → đảo trợ động từ: Hardly had I arrived…'),
  ('placement-v1:c2-1', 'placement-v1', 20, 'grammar', 'C2', 'multiple_choice', 'It was the lack of testing ___ caused the outage.', '{"options":[{"id":"a","text":"what"},{"id":"b","text":"that"},{"id":"c","text":"where"}],"correctOptionId":"b"}'::jsonb, 'Câu chẻ: It was + thông tin nhấn mạnh + that…'),
  ('placement-v1:c2-2', 'placement-v1', 21, 'vocabulary', 'C2', 'multiple_choice', 'His reply was deliberately ___, so nobody knew whether he agreed.', '{"options":[{"id":"a","text":"equivocal"},{"id":"b","text":"ubiquitous"},{"id":"c","text":"scalable"}],"correctOptionId":"a"}'::jsonb, '"Equivocal" = mơ hồ, nước đôi.'),
  ('placement-v1:c2-3', 'placement-v1', 22, 'reading', 'C2', 'true_false', 'Đúng hay sai theo câu văn?', '{"statement":"The minister made real concessions.","answer":false,"context":"The minister''s statement, while ostensibly conciliatory, conceded nothing of substance."}'::jsonb, '"Ostensibly conciliatory" (bề ngoài có vẻ hoà giải) nhưng "conceded nothing of substance" (không nhượng bộ điều gì thực chất).'),
  ('placement-v1:c2-4', 'placement-v1', 23, 'listening', 'C2', 'multiple_choice', 'What does the speaker mean?', '{"audioText":"Had we known the vendor would discontinue support, we''d never have built the whole platform on their framework.","options":[{"id":"a","text":"They regret choosing that framework."},{"id":"b","text":"The vendor still supports the framework."},{"id":"c","text":"They plan to build on the framework."}],"correctOptionId":"a"}'::jsonb, 'Đảo ngữ điều kiện loại 3 ("Had we known…") diễn tả hối tiếc về lựa chọn trong quá khứ.')
